insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "8f23080f-284a-4fc4-b9b2-4013d191e99a", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 2, "content": "Lindsay Rogers (00:03:38): Oh gosh, that is a big question. So I think first of all, it does come down to me being an athlete. I was an athlete. I struggled with these same things, but I didn't really know what I needed at the time, and I don't think a lot of athletes know that this is a skillset that they can get better at, that also can become a huge asset, not only in their career, but also as they go to hang up their skis or their climbing rope or whatever. We really wanted to give these athletes something that they could develop over time, but then paid significant dividends later in life as well, because we want to give them something that is sort of independent of the platforms and independent of the brands, because there's some crazy statistics out there about the mental health of athletes as they close in on the end of their career because they have no other skillset. (00:04:26): So part of what we're doing is equipping those athletes also for when their career starts to come to an end. And I think partly, again, I'm passionate about it because I've been there. I have tons of friends who have been on myriad of national teams and they all hit this point. So I think I'm personally invested in it because of the community that I'm in and where I was in the past. So I think that's why I care. It's something that's so fixable too. It's not something where it's like, oh, darn, they're out of luck. Too bad. There's no solution. There are really easy solutions to help them. So that's what we're aiming at.\n\nCole Heilborn (00:05:05): How do you define the problem? What is the problem that you're trying to solve?", "token_estimate": 410, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "00:03:38", "end_timestamp": "00:05:05", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "16ca5edd-42f6-4214-872f-221d25512c64", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 3, "content": "Lindsay Rogers (00:05:10): Yeah, it's a great question. So I would say there's a couple different things going on. One is that athletes, they are so focused on what we said a few minutes ago. They're so focused on what they're good at. They're so focused on being that elite athlete at the top of their game, trying to be better than anyone else, but that also leaves a little bit of a trail. They are gone a lot. So relationships have a tendency to suffer. They can't make a lot of money because despite what everyone thinks out there, where everyone's a high paid NFL athlete, they're not. There's some, again, statistics out there that's like 95% of professional athletes actually don't make enough to live. So they have to go on these crazy expeditions, raise money expeditions, meaning they're going to go raise money from friends and family, and they live on less than 40 grand a year and they do crowdfunding and all this stuff. (00:06:08): So it's one of those things that the problem persists both with the athlete realm, but it also, what we're seeing is that those brands don't have the internal resources and the skill sets to actually give these athletes what they need. So it's kind of a two-pronged problem. And then you have people, like there's great sports agents out there, but the agent world is sort of known for its scalping of athletes revenue. So there's all these kind of bits and pieces that are taking from the athletes, but we're not giving them and investing in their future as what skill sets are we going to give them so that they can have longevity in their career and beyond their sporting career. So that intersection, that delta of athletes having a primary focus on sport, not having a primary focus on finance and the other skills, and these brands also not having those internal resources to develop those skills, that that's where the problem lies. There's no one coming in and saying, Hey, we're going to develop these athletes in this way.", "token_estimate": 495, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:05:10", "end_timestamp": "00:05:10", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "6849d535-9544-4b7e-9997-68551939e601", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 4, "content": "Cole Heilborn (00:07:16): On the outside, I would assume folks might assume that, hey, these people get paid to have a logo on their shoulder or on their helmet and they travel around the world and they make six or seven figures. But that doesn't sound like the reality.\n\nLindsay Rogers (00:07:31): It's not the reality. I think there's so many assumptions with athletes. I mean, you had mentioned this, but I work with the United States Olympic and Paralympic committee, and those athletes are some of the poorest. They make hardly any money except for the top 2% of the athletes in that world. We're garnering a lot of attention. They don't make a lot of money, and it really is what happens is that it makes the case for these athletes having very short career. They financially cannot sustain the career, even on their skillsets might be there, their athletic ability might be there. So I think it's a misconception that these athletes make a ton of money. I mean, again, the're Jimmy Shins of the world, there's those people who, yes, so the top their game, they're also making money from other sources. So not just making money from climbing, they're making money from speaking gigs and movies and all the things. So that's other thing is we are looking at these athletes as these one dimensional characters where we just need them to speak to the brand versus also equip them as business people. They have to be thoughtful about building a sustainable business as an athlete. So those are kind of the skills that we're trying to give that.\n\nCole Heilborn (00:08:44): So I'm curious if you could back up a little bit and provide a little context to your role as an athlete. And you mentioned that athletes are often perceived as one dimensional people. Did you realize that about yourself at some point in your career of being an athlete?", "token_estimate": 461, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:07:16", "end_timestamp": "00:08:44", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "61a92e88-c89a-4dce-85e3-dcf633f78979", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 5, "content": "Lindsay Rogers (00:08:57): Yeah. It's interesting. I was just revisiting this myself thinking about this recently, how when I was an athlete, I think there were a few things going on. One is that, and I hear this from every single athlete I work with, they say, I don't want to be seen as just an athlete. I'm more than that. And I think I hit that too, where I had all these interests and other things that I wanted to do. I wanted to write, I wanted to be a freelancer, all these things. But you kind of get pigeonholed as you can't do both. You're supposed to be good at this one thing, stay in your lane. And so it's really hard for athletes to be sort of multidimensional and break outside of that stay in your lane box. And it is shifting. I feel like in the last year, this has changed pretty dramatically, and we can get into this, this is very representative of why athlete rosters are changing really dramatically. (00:09:47): But I do think for a long time you were supposed to just be an athlete, and there's people like Caroline Gly, she just announced that she is running for Senate. She's getting a lot of pushback. I am a huge supporter of her doing this and young people being multidimensional and doing other things besides just their sport, but she is getting a lot of flack. And so I think there's still this hangup of athletes, stay in your lane, do your thing, head down. Just do that. We only want you to inspire us with your physical ability. We don't want to see you as something else. So I think what happens is that singular identity can be the kind of mental death of athletes because they don't see themselves as anything else. If they do start to lean on other parts of themselves, it starts to become really chaotic. Who am they start to ask themselves, who am I? And so other people start not understanding who they are, what they represent. So there's a mental health component to that. Absolutely.\n\nCole Heilborn (00:10:49): Yeah, no kidding. So tell us a little bit about your athlete career. What did that look like? What were you a part of?", "token_estimate": 520, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "00:08:57", "end_timestamp": "00:10:49", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "917f615e-ca54-4731-b117-c5073a350f47", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 6, "content": "Lindsay Rogers (00:10:57): Yeah, so I started, grew up in Aspen, Colorado, and I grew up ski racing, so I ski raced through Noam and then a couple of Europa cups over in Europe. And so I was on, I think they organized the US ski team a little bit differently now, but they had this development team of the US ski team. So that's the point I got. And then I had a pretty huge injury that I, I'll spare you the details, but I was a pretty kind of career ending injury, had lots of fractures up and down both my legs, and so it was really hard to recover from. And I was just speed a speed skier, so mostly super G and downhill. And so when I went to college, they only focus on tech events, GS and sla. And so that's kind of when I started to hang 'em up. (00:11:43): And then after I left college, I opened the door again and started doing more big mountain skiing, did a few of the competitions, but then started doing more expedition skiing, so traveling over the world, try to climb and ski big peaks. And that's when I started working with several different brands. Again, growing up ski racing, I had the sponsors, but it was very, very siloed in ski racing. There was no personal brand back then. And so when I started doing more of that expedition style skiing, I started working with Mountain Hardware and all the ski companies and brands and K two, it was interesting, and it was also one of those experiences where it left me with a lot of questions. What do you want me to be doing? What am I supposed to be doing? Am I supposed to be talking about you out there? How do you want me to be talking about you out there? So I felt sort of this wash of confusion. I didn't really get any really clean answers from anyone or any directives. And I think that's the case with a lot of athletes. They sort of feel like, well, I know I'm waned by you, but what do you want out of me and how am I supposed to do that? You are expecting these things from me, but I don't really know how I'm supposed to do it. So that's what I experienced as well. (00:13:02): I started kind of pouring my athletic endeavors into writing as well. So I would pick expeditions where I could write feature articles for magazines. So I started working a lot with outside and National Geographic and all the other ones in between. And so that started taking a little bit more precedence for me is working in terms of what I could get a story out of versus what's the big thing I could go ski. So I started working heavily in that genre of writing more and more. And then I also went to what the industry calls the dark side and started working more with brands. Also, it was the time when that narrative side was starting to embed itself into the marketing mechanisms, and a lot of brands were iron writers. And so I started working a lot with brands on how do you integrate that narrative infrastructure into your marketing messages, and that's when things shifted pretty dramatically.", "token_estimate": 741, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:10:57", "end_timestamp": "00:10:57", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "29069b80-6f92-4032-866c-9a9517548e6c", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 7, "content": "Cole Heilborn (00:14:01): If you had to describe a perfect relationship between a brand and an athlete, what does an ideal state look like?\n\nLindsay Rogers (00:14:09): Okay, I would say it's funny, there's a few different brands who are doing pieces of this really well, and I won't name them quite yet. But what I would say is a brand needs to look at an athlete as a holistic vehicle, so a holistic brand, not just their athletic endeavors, not just the things that they're interested outside of their athletics, but as a whole, the characteristics, the values, what they've been through, what they can talk about, and then also go in and say, Hey, these are our brand values and how do you connect with our brand values? And then really set the stage for we have all these different athletes as part of our roster, and you have this really solid message. Why don't you focus on that? This other person has this other solid focus for their messaging. You focus on that and also look at the intersections of those athletes. (00:15:06): How are those relationships being developed between athletes? Because people are very fascinated in that with how the athletes interact with each other and how they do the things that they do on their own. Because a lot of these athletes are very independent and training on their own. So for brands, I would say really look at a holistic person, not just their physical abilities, and then also look at how can that person connect with their core consumer or even beyond their core consumer. What are those things that are interesting as a human? Because ultimately there's a lot of studies being done on how people react to not just athletes, but how people react to messaging. There's two things that we as humans are really, really react well to. One is creativity and one is humanity. And I think in the past 15, 20 years, the humanity of the athletes has sort of been pulled out a little bit in lieu of focusing on their athletic achievements. (00:16:12): This is the Red Bull model of we're going to bring you in, we're going to wash you off, clean you up, and we're only going to put you on the roster if you are ping over and over again. As soon as you stop performing, you're out. So that I feel like that model is slowly being retired because it's really hard to connect to as a human. So I think brands really need to look at the humanity behind these athletes and what are they doing that's creative and interesting, and not just climbing Everest, not just doing that big peak.", "token_estimate": 632, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:14:01", "end_timestamp": "00:14:09", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "dfff4ea5-a424-447b-8f40-5fcedcd5398b", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 8, "content": "Cole Heilborn (00:16:45): This is really fascinating. This is something I've been thinking about and I'd love to bounce this idea off of you. (00:16:51): So I see this often, I feel like brands will go out and produce a film about an athlete or an ambassador, and maybe I'm seeing this because we're still kind of in the middle of this transition, but it seems like there's a lot of content that gets created that's purely focused on the physical, it's purely focused on peak bagging, it's focused on the FKT or whatever. And those are impressive, no doubt. But as you said, it's hard for the general population to relate with that athlete because we don't know what it's like to summit Everest, but what we do know, what we can relate on is the humanity level. We can relate on those values. And so I feel like there's this massive opportunity to either find athletes who have more of those humanity stories or emphasize the humanity of the athletes on teams. But is that something that you see? Are we kind of in this middle ground where we're still focused on physical, but we're also focused on the humanity? And we haven't totally blended those two worlds.", "token_estimate": 291, "speakers": ["Cole Heilborn"], "start_timestamp": "00:16:45", "end_timestamp": "00:16:45", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "be705c4d-9cef-4f60-9807-6126a74df926", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 9, "content": "Lindsay Rogers (00:17:54): I think we are right in the middle of a transition right in the middle, and I think last year was a really interesting year. I mean, there's so much going on last year in sports, and I'll just name a few trends and then I'll get back to your question. But one is that we were looking at athletes are now really, really becoming the facet of those sports teams leagues, et cetera, more than they ever have been. Women, obviously, the women in sports became a huge trend last year, and brands are really starting to shift their focus into the holistic female athletes. So they're looking at training female coaches, how are we elevating coaches into new realms of the professional sports world? Barbie came out, all those things that are supporting the female athlete. Then we have obviously there's all these shows on streaming platforms. So there's this almost like a democratization of sports, and I think that's trickling down into the rosters where you're looking at how brands are really taking that, for lack of a better term, citizenry of the people who they want to connect with of their consumers and infiltrating it into their brand or their athlete rosters. (00:19:12): And so what that looks like is the North Face, for example, last year I've worked with them for a while with all of their different athletes and they had something called, I think it was called the Athlete Development Program, where they put out this kind of call for pitches and applications for everyday athletes out there in the world. And it was really I think a statement on, Hey, we're not just looking for the Everest climbers of a Jimmy Chen's of the world, and those are great, they kind have to have those as the top of the pyramid. But we're also looking at how are we bringing in this idea of different races, different cultural backgrounds? A lot of the DEI is kind of starting to come into this fold and this conversation around who are these people and how are people connecting to them? Because brands see that if they focus on one type of athlete, they're going to get one type of consumer because they are the face of the brand. (00:20:11): So if you look at that spreading out or democratization of those athlete rosters, I think it allows people to connect more deeply emotionally with those athletes if they have these different tiers. And I know you and I talked about this really briefly, but last year Eddie Bauer kind of made this big splash. They literally overnight fired their entire athlete team, and I think some of them had a hint that it was coming, but they did it. They fired their high level athlete team, but then they rehired a bunch of people that were more like a highly varied group of photographers and fishermen and adventurers because they did want to spread that across a wider spectrum of people so people could connect more deeply with who they were and they could see themselves in those athletes because as you just said, sometimes it's really hard to connect with people who are climbing marrow or Everest. I am not going to do that. Most people are not going to do that, but I will connect with someone who's going on a five hour about bike ride or pushing themselves at a particular event. So really understanding what those human elements of those people are, those everyday people, and highlighting that humanity behind those people I think is really where it's going.", "token_estimate": 857, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:17:54", "end_timestamp": "00:17:54", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "7a45300f-6cd4-455c-828b-d40b1a885301", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 10, "content": "Cole Heilborn (00:21:30): It sounds like the industry is filling out the pyramid of athletes.\n\nLindsay Rogers (00:21:35): I think so, yeah. But I also think what's interesting too is I mean you can look at the outdoor industry, but if you look across just sports in general, more traditional sports, there's really interesting things happening as well where there's creative directors are being hired by teams. So never before has a hockey team had a creative director. So it's not the brand that's hiring a creative director, but it's actually like these teams because they are seeing that culturally people are really interested in athletes being these everyday people who are wearing clothes and going to the grocery store. They're like us. So yeah, I think there's that, that natural evolution towards back towards how do we connect as human beings now on a very basic level.\n\nCole Heilborn (00:22:25): And that's what I see the opportunity in storytelling. It's like if you can take someone who has an incredible physical accomplishment like someone in Everest, but then you build in those scenes where there's moments where they are going to the grocery store or they are paying their taxes or paying their rent, I feel like those are the moments where you get to relate with someone and you get to realize it takes them off the pedestal and they're like, oh, they are just a regular person. Sure, they're doing this crazy expedition, but they're very much like me. And I feel like that's something I would love to see more of specifically in documentaries and films and the ability to relate with an audience.", "token_estimate": 404, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:21:30", "end_timestamp": "00:22:25", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "7062d278-25ca-4a49-a9dc-dbb9b31a3698", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 11, "content": "Lindsay Rogers (00:23:04): Yeah, I mean I think not to pick on companies like TGR, but sorry, TGR, I'm going to pick on you for a second. So when I go to those films and I grew up seeing Warren Miller, the Warren Miller films and you have all the bloopers and it's really funny. And what I think TGR has missed unfortunately, and I think there's the other companies like them have missed, is that people walk away, the kids walk away, the adults walk away wondering who are those people all is how big they win. You have no idea who these people are, you have no idea where they grew up, what their hardship was, what they went through, what they've learned, how they have become who they are. And ultimately that's what people care about because again, it's like a disconnect between what they're doing and what I'm going to be able to do. (00:23:52): But there's also this universality of the struggle, the hardship, the pain, all of those things that we all go through as human beings living in the world that I think companies like TGR brands can really leverage what these athletes have been through. Because one of the big things that we talk to athletes about is this, and leaders actually this is very, very important for them as well, is this idea of you want to connect on this shared identity, right? I am this, you are this. We are both this thing. So if you can say we are both this thing, it really builds this kind of intimacy and trust between you and them. So there's less of that tension between you and them and more of that connection. But then the other piece that I don't see very often, and this is where we really do a lot of our work, is really figuring out what have you been through? (00:24:50): What has it caused in you? What reaction has it caused in you? How have you righted the ship, changed your process? What have you done because of that hardship when your back was up against a wall, you had to make a decision. And then how has it changed what you do today? And then the key thing that I feel like we're really trying to hone in on is how does that impact other people? How does that impact other people? Because athletes are so focused on the lens being on them that as soon as they start to shift over to how what I've been through can impact other people, the brand wins, they connect way deeper with audiences, et cetera. So that piece is a really, really key piece of how we start to coach athletes is how do you shift your experience into something that other people can benefit from? And as soon as brands start thinking that way too, all of a sudden they have influencers that go far, far deeper than selling clothes, than selling gear. They have those people that are deeply connected to their audience. So that's my mission. I want people to share that stuff.", "token_estimate": 702, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:23:04", "end_timestamp": "00:23:04", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "66d7a4b8-21de-4f3b-adaf-ac78bc6155ab", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 12, "content": "Cole Heilborn (00:26:00): Why do you feel like that is, why do you feel like those aren't things that are typically shared or are flushed out?\n\nLindsay Rogers (00:26:07): I think it's hard. I think it's harder. It's a lot harder than saying, I went to the grocery store. It's a lot harder than saying, I have this dog who cuddles up with me on the couch, or I trained 10 hours lapping the ice, fall in your ray. It is harder to figure out and you need someone sort of like an outside source helping you and asking you really hard questions and then saying, Hey, this is an opportunity. And really pointing out the patterns and connecting those dots with you is it's like I'm a big fan of therapy. I think everyone on the planet should go to a therapist because what they do is they can help connect the dots for you. Oftentimes we just need someone else to do it for us and help us. And so I think it's partly that it's just not a vernacular that these athletes or brands have really been taught, but I think to compete today in the world on that human level, you have to go there or else that kind of vulnerability and intimacy is just not going to come.\n\nCole Heilborn (00:27:09): So you mentioned that athletes historically are typically one dimensional. Do you feel like if athletes can start to answer this question or kind of round out this part of their life, it will make them multidimensional?", "token_estimate": 351, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:26:00", "end_timestamp": "00:27:09", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "5555ffc9-2504-4155-8e90-64c81ac17e3f", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 13, "content": "Lindsay Rogers (00:27:20): I'm going to shift what you said just a tiny bit. I think they are multidimensional. I think that other people see them as one dimensional and they absolutely hate it enough. I'm not kidding when I say every single athlete and I give them a huge list of questions where we start working together, I say, what is the biggest challenge you have? And they say, being seen as just an athlete. And so I think they all have these multidimensions. They're afraid to share them because I think they're really afraid that their audience is going to look at them and say, what? I'm not into this side of you. I only liked that side, which can happen to be fair, that can happen. It's a risk. But I also think younger generations in particular are, I mean, I'm sure you've seen these studies too, they're very, very focused on what a brand stands for and what a person stands for. (00:28:13): And they'll get behind you if they know that if they don't know what you stand for, they're not going to have staying power as a supporter of you. And so I think these athletes have to do the work to figure out what are those dimensions? How do I want to be perceived? How am I showing up? What am I saying? That really ladders up to that idea of who I want to be perceived as. And sometimes it requires, we have this three-step process that we talk about where it's sort of this unbrand rebrand and reeducate. And the unbranding piece oftentimes is these athletes get to a point in their career when they're like, well, but I'm seen as this thing. I've always been seen as this thing. How do I distance myself from that one thing? So we have to go through this unbranding process, then decide, okay, well how do you ought to be seen? (00:29:03): How do you want to be perceived? What do you want people to know about you that's going to change that perception? And then we go into the reeducation piece that's like, okay, this is what we're going to start to put out there to reeducate this audience on who you are, why you're meaningful, why you're going to have impact on their life. So again, it's a process, but I think for them it really opens up this sense of relief of like, ah, I'm not just that one thing. I don't have to just be that thing. Thank you. So it's really cool to see them connect the dots too of like, oh my God, it's like a pressure valve, at least It's so neat to see.", "token_estimate": 601, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:27:20", "end_timestamp": "00:27:20", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "a1a46d27-910b-4145-8977-29f8ca1b4da0", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 14, "content": "Cole Heilborn (00:29:40): Is that possible with the way that most brands work with athletes today? Are brands equipping athletes to encourage them to round themselves out and figure out who they are and who are they beyond just the podium? Is that doable in today's world?\n\nLindsay Rogers (00:29:59): Absolutely. I almost think it's a must do to be able to kind of compete at that level. And I think the beauty of all of this focus on mental health with athletes is that they are shining a light on, we do need to route out these athletes. We can't just put them in this pressure cooker and expect them to be everything we want them to be, but we need to kind of round them out. And so absolutely, I think it's a hundred percent possible. I think brands are more and more open to it, and I think they're seeing success of other athletes and other brands doing this very well. And I think there's people that I could point to. I mean one just because worked with her, Hillary Nelson, unfortunately, she passed. She was really starting to do this a lot and really starting to open up that vulnerability door and people were looking at her as kind of this person that's piercing this veil, finally, you're talking about these things that no one has elevated before, and now I get you more. (00:31:01): Now I can connect with you now I see why you do these things. Whereas before, she may have been judged for being a mom on an expedition, when she explained why and drove her, people started to get it and support her a lot more. So I think when brands see those success stories or brands kind of take a risk in elevating those elements of the athletes and they see how well it resonates, then they're more willing to do it over and over again. And so I think it's shifting from brands seeing it as a risk to brands seeing it as a must have, and they're figuring it out. I mean, hopefully they'll bring, whether it's me or someone else in to really help do this in a thoughtful way because you don't want to do this. I think you can do it very inauthentically and have the opposite effect. So I think you want to be thoughtful, slow smart, and really elevate the stories that enter deeply meaningful to the athletes, but then also deeply meaningful to the audience.", "token_estimate": 566, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:29:40", "end_timestamp": "00:29:59", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "33ba2535-d442-414a-8760-edc1fda85437", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 15, "content": "Cole Heilborn (00:32:00): Do you feel like audiences are inspired differently today than they were say 20 years ago?\n\nLindsay Rogers (00:32:08): Yes, but I also, it's interesting. I think they are inspired differently. Actually, I don't know if I would say inspired differently. I would say their expectations have shifted. I think if you look back across humanity in general, and there's all sorts of, again, not to point to studies, but there's all sorts of studies being done on this right now where from a psychological perspective, people really want a few different things. They want a sense of meaning in their life, they want sense of belonging. I belong to this type of group that I connect with or that I have similar functions in. And then there's this idea of psychological richness. And this is something that's kind of come up more and more recently where people want to experience something that makes them their life more rich, more interesting, more challenged. And I think that's a shift that may have happened from a brand and athlete perspective is that people are still inspired by those kind of deep human stories that Johnson and Johnson does at the Olympics, for example. But so I don't think what they're inspired by has changed, but I think their expectation around wanting to be enriched by these stories has shifted. They're not just looking to be in inspired. They also want to have that aspirational could, that could be me. I understand them, maybe I could do that. So that has shifted a little bit I think.\n\nCole Heilborn (00:33:40): Interesting. I've never considered the difference between inspired and enriched and where that line is. But it sounds like you're saying if you can enrich someone, maybe another word for that is empowered you them, you help them see a potential path they could take where I feel like inspired is just like you kind of walk away with your mind blown and you're like, oh my gosh, but there's no way for you, me as a viewer to feel like I could follow those same steps. Is that kind of what you're saying?", "token_estimate": 517, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:32:00", "end_timestamp": "00:33:40", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "3272801f-7445-41e2-9f99-a9014016341d", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 16, "content": "Lindsay Rogers (00:34:08): A little bit, yeah. And I think there's this other element when we talk about that enriched, it's also this idea of shifting perspective. So it's not just I get to see the potential of what I could be because you're showing me a way, but it's also this idea of, wow, I've never thought about it that way. That's so interesting. Now I have this different view of it and I'm going to come back to you for more because that was really cool. I've never heard someone say that before. So that type of enrichment where you're just literally giving people this slight shift in perception and perspective that they didn't have before. And that's a big one. What we coach athletes on and a lot with leaders is that how do you shift someone's perspective? Because ultimately if you do that, they start to pay attention because our brains say, oh, that's new. I got to come back. That's new. I learned something there. So I think it is more than, how can I also do that thing? It's about saying, wow, I learned something there that I never imagined to be true, and that's enriching.\n\nCole Heilborn (00:35:13): It's 2024 and we're in this crazy world of digital marketing and the attention span economy is, well, there's tons of studies out there, but it's short and it's only getting shorter. It feels like this need that humans have to feel enriched could be at odds with the way that we're consuming and engaging with media, but I almost feel like that creates more of a need for enrichment in our lives. But how do, as an athlete, how do you break through that if the way that you're interacting with people is changing? How do you see those two pieces playing and evolving?", "token_estimate": 424, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "00:34:08", "end_timestamp": "00:35:13", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "e6390c17-5783-4cc9-8d9f-6cd604693dff", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 17, "content": "Lindsay Rogers (00:35:51): Yeah, I don't disagree with you that they can be seen as at odds with each other. Absolutely. Because I mean, not to drop numbers, but I think people say, but you have between three and seven seconds to grab someone's attention. So if you're looking at social media for example, and you have between three and seven seconds to snag someone on a story, then what we do is we say, how do you shift their perception or perspective right up front to give you the ability and that flexibility to drag them along a little further? If you do grab them right up front, it gives you more flexibility, more leeway to shift their perspective or do more tell more story later. And there's also, there's trends heading in the opposite direction also. So your podcast is in seven minutes, you have Rich Roll, you have Tim Ferriss, they have 2, 3, 4 hour podcasts that people are wanting a little bit more deeper information versus this very little information across a lot of different topics. (00:36:55): People are starting to realize that, wow, I don't really know much about a lot, but I want to know more about fewer topics. And so that trend is going in a couple of different directions. And so we always kind of slow growth over fast growth. I'm not one to focus on the viral nature of what you're going to put out there because that has absolutely no sustainability whatsoever. So we focus very much on what's meaningful to you, how do you build an audience that is going to stick with you and that believes very truly in who you are and what you're doing versus that quick one-off story that's going to grab headlines, and they could be helpful briefly, but oftentimes the gold medal is not going to be what people are interested in six months or the fact that you tagged that peak. People aren't going to be interested in that in six months, but they will really remember how you feel, right? (00:37:49): And this is, I mean, marketing 1 0 1, but data and facts do not leave people with, it doesn't evoke emotion. And so when we try to grab someone in that three to seven seconds and then we kind of build upon that and allow people to feel something because it hits them and connects with the universality of their emotions, then it gives people more flexibility in how much time they can spend with their audience. So that was a long-winded way of saying it is a challenge, and I think it'll continue to be a challenge, but I think there's a swing slightly away from short, quick virality stuff and going more towards meaning.", "token_estimate": 638, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:35:51", "end_timestamp": "00:35:51", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "20252edd-673f-4c3e-8780-2da25d0f501e", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 18, "content": "Cole Heilborn (00:38:33): Yeah, people aren't afraid to go if it's a medium and a person that they trust. That seems like massive opportunity for an athlete. I think about Payson with his podcast, the Adventures Dash podcast. What a great example of an athlete who's taken his position as an athlete and then gone super, super deep and gone in a direction not many other athletes have gone before.\n\nLindsay Rogers (00:38:56): I agree. And again, it's that example. It's Caroline Gly, it's all these people who have taken their platform and used it for something that is beyond the scope of athleticism. And so I think it's a real door opener for them. Again, what we were talking about, these athletes will not be at the top of their physical game for long. How do you give them the tools that they can use and how do you get them to think outside the box to do something beyond the summit so that they can have a career and something to lean on when they do leave that sport or when they retire from the professional level. So yeah, I think there's endless opportunities and examples out there of people doing that. And it takes courage. Absolutely. I think it does require them separating themselves slightly from just being an athlete. So yeah.\n\nCole Heilborn (00:39:53): Whose responsibility is that, the brand's responsibility to initiate this or how do you see that playing out?", "token_estimate": 346, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:38:33", "end_timestamp": "00:39:53", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "7672797b-e9d2-4a71-aa58-8ff538055159", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 19, "content": "Lindsay Rogers (00:40:00): People might disagree with me on this, and I'm completely okay with that. So I do feel like the brands are leveraging these athletes as they're front door into their marketing. This is how we're getting people interested in us is by using these athletes and what they're doing. So if the brand is using the athletes to that degree, it's my belief that it is their responsibility to tool up these athletes and skill up these athletes with exactly what they need to reflect well on the brand. Why wouldn't you do that? It seems like an obvious win-win where you give athletes this skill and this tool and then it reflects really well on the brand that has a longer sustainable relationship versus that as these athletes kind of peeling off really quickly. So it is my belief that it's on behalf of the brand to give these athletes that initial nudge and that initial support to say, we don't want you here just because of your podium, just because of your summit, just because of those things. (00:41:02): We want you here for a long period of time. Here's what it's going to take on our end. And really giving them those resources and that support and not doing the kind of Red Bull method of cutting them as soon as they're off the podium. So I think that can have pretty drastic effects on these athletes and their mental health. So I think it's incumbent on the brand to start that process. And I think it's also incumbent on the athletes to ask the brands, Hey, I need this support. There's all sorts of studies on rising leaders in the corporate world on how they're asking of their corporate environment. They want much more support on the learning and development, personal growth, professional growth side, and I think that is going to start to have a trickle down or want it to have a trickled out effect in the athlete side. (00:41:52): I think they need to keep asking for it, and the more they ask for it, the more the brands are now respond. So I think it's two. I think inevitably these two, it's a relationship. They have to trust each other, they have to give each other something. So the athletes oftentimes don't really know what they need to give back to the brand. So that's where I do feel like it's s comment on the brand to say, Hey, this is what we need. Here's how you're going to do it. Ask any questions. What else do you need from us? We're going to lean on you heavily to bring the consumers in.", "token_estimate": 613, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:40:00", "end_timestamp": "00:40:00", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "9a99e1bb-9699-4b5b-a234-87ea64c6c7fe", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 20, "content": "Cole Heilborn (00:42:27): Do you feel like brands are under equipped or under staffed? And is this why there's maybe a gap between the potential that an athlete team could be and what it is?\n\nLindsay Rogers (00:42:38): Oh, a hundred percent. And it's not just brands either. It's like when you look at, again, kind more the broader sport world, it's teams, leagues, national governing bodies. They're under equipped, but they're not supposed to have to do that. They haven't historically really needed to equip athletes on this level. But I think because consumers are asking for more depth, they're asking for humanity, they're asking for that creativity, it's becoming a requirement to compete. And so I think some brands, I'm not going to say all brands insane. Some brands do this very, very well, and I think they're realizing, Hey, we do need this as just part of the regular run of business. But I don't think it's everywhere in the outdoor industry, partly because people are in the outdoor industry because they love it, it's passionate. It's not some massive moneymaking scheme in the outdoor industry typically. (00:43:36): So I think resources are a little bit tighter when it comes to brands. And so I think there's also a great consulting culture out there now where brands are hiring consultants, freelancers to come in and help with these things. And I think that's great, and I think they should not necessarily feel like they need someone full-time to do this, but I do think they also need to equip their internal staff to say, Hey, we need to start elevating that humanity. How are we going to do that? What's our program? So if they can give their internal teams that language, that vernacular to start to kind of broaden what they're doing, great. I don't think they have to have those internal resources. They can easily get them outside.\n\nCole Heilborn (00:44:25): What are some other roadblocks that you see or you foresee that will get in the way of athlete rosters reaching their full potential? I mean, anything from the brand side, from the athlete side, external forces.", "token_estimate": 525, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:42:27", "end_timestamp": "00:44:25", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "2a4520ed-7182-4e21-8f81-1cc0c0ab0147", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 21, "content": "Lindsay Rogers (00:44:41): Yeah, that's a good question. I think there is a level of vulnerability and courage. It takes a path of both the brand and the athlete to do what I am suggesting, not the easiest path. It's a little bit of a harder path, but a more meaningful path. So I would say there is a little bit of resistance sometimes with athletes to say, this feels very exposed. I feel like I'm exposing some pieces of me that I'm not comfortable with. So younger athletes, it's a little bit of a harder push to get there. Older athletes are like all day long, all day long, bring it. I love this stuff. So I think there is that piece though where there can be some resistance on behalf of the athletes to say, wow, this is a new way. This is a new way of doing things. And anytime you introduce something new, there's a little bit of pushback. (00:45:37): So I think that's one. I would say resources always. So not necessarily resources internally at a company, but just financial resources to bring in the right level of professionals to help educate these athletes and the brand on what needs to be done. I think we've seen Covid do really interesting things in the outdoor industry where it kind spiked, it flattened at the beginning, then it spiked it, and now it's kind of leveling off. And so what's happening is that obviously the first thing to go with any company is their marketing budget. And typically the athlete world falls within the marketing budget. And so there's the ebbs and flows in the reality of that world. And so I think that can always be a challenge, but I also see this as you talk to a lot of people about marketing obviously, and I think as soon as you cut that, you also cut your connection with consumers. And so I think that can always be a challenge, the ebb and flow of the resources. But I do think as soon as they get into more of a cycle of producing content and producing these stories that do elevate humanity, they'll see returns in a bigger way. So it's harder to use that excuse.", "token_estimate": 508, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:44:41", "end_timestamp": "00:44:41", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "9dee4639-695f-430d-81da-94cf3ab3b510", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 22, "content": "Cole Heilborn (00:46:55): What's your take on, you mentioned elevating humanity, which I love. That's a neat phrase. What's your take on the industries, how the rosters have been changing? As we were talking about filling out the pyramid, some brands are cutting off the top, so to speak, as we're adding more and more people to rosters and we're adding more and more people who maybe aren't at the very top of the physical game, what challenges, but what opportunities does that present? How do you see that playing out? I guess I talked to some brands and I talked to some athletes and they see that as a concern. It's like, oh, are all people who are peak bagging going to be no longer have a job anymore? But obviously there's a balance to it all, but how do you see that? And I guess what's a healthy model look like?", "token_estimate": 206, "speakers": ["Cole Heilborn"], "start_timestamp": "00:46:55", "end_timestamp": "00:46:55", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "fc65b06c-6deb-466e-ac00-502c21a72f84", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 23, "content": "Lindsay Rogers (00:47:45): I think there's going to have to be a little bit of a combination of the peak baggers, the high level athletes who are doing things that no one has done before, because I think that is exciting. It's very exciting to watch. It's very exciting to participate in. There's no denying that. I think just who we are, again, as human beings, we like to get behind people who are trying to do something we didn't think was physically or emotionally possible. So I think we'll always have that level of the pyramid, and I hope we do. It's exciting to me to think about people pushing the envelope on any number of sports. It could be traditional sports, it could be climbing, mountaineering, whatever it is. So I think that's okay. We absolutely have to have that element. What I would love to see is that we're not just saying so-and-so climbed the 22,000 foot north wall in the kubu or something. (00:48:46): We're talking about that not being the primary focus or not being the only focus. We're talking about the depth of what it took to get there, what sacrifice they have to make, what's happening with the people at home, the fear, all of those kind of real things. And so I would say, again, we'll continue to have that side of the athlete roster. I think filling it out with programs that are a little bit more broad in terms of DEI, but also just how do you ask your consumers what they want? What are they interested in? What do they hope, dream fear, aspire to take the answers to those questions and start to hire athletes that connect to those answers that give people what they want to experience. Because there's going to be some of your consumers who don't want to be scared watching the alpinist. (00:49:43): There's going to be people who sweat thinking about someone climbing marrow or whatever it is. So we want to think about are there people who are in your consumer base who want to experience something totally different? What is that? Do that research, ask those hard questions. Ask those not demographic questions, but psychographic questions of your consumers. And then connect the rest of your athlete roster with that, with what those consumers want to feel, what they want to experience, who they want to become, all of that. Because if you're not asking those questions of your consumers, you're missing the mark big time with your athlete roster. So I think that's a huge opportunity for people and for brands, is to ask different questions, ask harder questions, and then connect the roster to that.", "token_estimate": 638, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:47:45", "end_timestamp": "00:47:45", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "442f4890-7ae5-419f-9e61-d0279dd40059", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 24, "content": "Cole Heilborn (00:50:32): Something that I've heard from previous guests and some of our clients is they don't want to by adding more people and kind of backfilling this pyramid, if that's the analogy we're using, they don't want to lose their core consumer. They don't want to lose the extreme small percentage of their population of their customers who are out doing those hardcore things. Is that a risk that you see as legitimate or I don't know, does that really matter?\n\nLindsay Rogers (00:51:03): Absolutely matters. And again, I don't think I'm going to be the person who's out there telling people to get rid of their high level roster because I am one of those people who finds them endlessly fascinating with how on earth do they pull that off? I want to understand it deeply curious about people, and I think other people would put themselves in that category. So I think there's a risk to pulling an Eddie Bauer when getting rid of everyone on that high level and just going after the base of the pyramid, and not that either one is more or less important. I do think it's really smart to have both, because there's different people who want different things from you. And if you're a Yeti, it makes way more sense to have the fly fisherman and all that because you're not necessarily carrying a cooler the top of Everest. (00:51:57): So that makes sense. And I think that's where you have to really look at who your consumer base is, because you might not be the person or the brand who needs someone climbing at that level, and your base is moving more towards really wanting to connect deeply with the everyday experience of, and that becomes more of an ambassador program. So it's slightly less of an athlete roster, more of an ambassador program. So that's a shift too, is that I have seen that brands have athlete rosters and then they have an ambassador program, and those are two very different tiers. The ambassador program is the everyday people out in the world getting you excited about using that product in your everyday life. And then the athlete program is a little bit that higher tier. So I will not be in the camp that you should get rid of your higher tier athletes. I think you should have both, but also, again, build those rosters so they are deeply connected with what your consumer base is looking for and what they want to experience.", "token_estimate": 594, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:50:32", "end_timestamp": "00:51:03", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "7bc21a0f-dbc1-4be4-bf70-0f90f43e5ae3", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 25, "content": "Cole Heilborn (00:53:01): I love how you described it at the beginning of the show. You said identify what your needs and what your communication objectives are, and then find the athletes either who exist on your team already or who find new athletes, and then just draw the connection between them. It's such a simple strategy, such a simple idea. Obviously as everything we talk about is simple, an idea, but much more difficult in practicality. But that's a really neat way to think about it.\n\nLindsay Rogers (00:53:28): Yeah, again, it's really interesting when we work with people, we have, one of our sessions is strictly focused on audience and the questions we give them all these questions to ask. They're potential or existing audience, and some of them are like, are you kidding me? You're going to make me ask these questions because quite personal. And it's things like, what do you want more of in your life? Do you want more time? Do you want more meaning? What do you want less of? What are you afraid of happening? Some kind of deep questions. And I do feel like brands are, especially in the outdoor industry, they don't ask those questions very well or very frequently, and therefore they build athlete rosters. They build our communication strategy around an assumption, around assumptions that these consumers want to experience this particular thing without really asking deep hard questions. So again, I mean, to your point, what you just described is asking those hard questions and then connecting them to the right person to kind of put those into action. You're connecting 'em to an athlete or an ambassador who lives out what your consumer says they want to experience. So yeah, it's a slightly inverse way of doing things, but one I suggest, I\n\nCole Heilborn (00:54:42): Mean, those seem like basic questions to ask, and they seem like they would be highly productive and fruitful when you're considering, if we only have this much money to deploy, let's make sure it's a really good investment. Why do you feel like those questions aren't being asked?", "token_estimate": 521, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "00:53:01", "end_timestamp": "00:54:42", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "b5375d8e-4607-4fec-9bcf-7ead859fd9d0", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 26, "content": "Lindsay Rogers (00:54:57): I've been a part of several focus groups for outdoor brands, and often it is very focused on product, right? Do you like this product? Does it feel good on your skin? Can it get you out running in the cold? And does it keep you warm and dry? So for brands in the outdoor industry, it's heavily, heavily focused on that physical experience, and I think there's other brands that are doing the outside of the outdoor industry. I always, always give examples to both athletes and leaders who we work with examples outside of the outdoor industry because they do it very differently oftentimes, and they're not so focused on, it's very specific to the outdoor industry that you're focused on the physical experience of these products. (00:55:44): I would say that we encourage brands in the outdoor industry to ask these more emotional focused questions because it is, not only does it help you understand your consumers in a very different way, but it also helps the consumer see you as someone like, wow, that brand is asking me that question. They're bringing me into this conversation on that level. They must really care about me. So it's that idea of you're going to get a lot out of it by asking these questions of these potential consumers, but they're also going to see you in a completely different way because you're asking them that. So I dunno, I think it historically has felt a lot too soft or potentially too risky to ask those questions. And why would we need that? And well, we need to know if it's warm and waterproof. And now we're getting into an era where it's like, no, people have to actually believe in you as a brand before they even purchase a product.\n\nCole Heilborn (00:56:46): I mean, all the brands are making great products. Everyone is making something that's outstanding and is warm and waterproof. So if we're all competing at the same level or similar levels, what else? How do you go further? How do you go beyond, to your point,\n\nLindsay Rogers (00:57:00): Completely agree. Yep.", "token_estimate": 510, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "00:54:57", "end_timestamp": "00:57:00", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "9b7d9976-aec5-4477-b6c4-eb13851d302f", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 27, "content": "Cole Heilborn (00:57:02): We haven't touched on this much, and this might be a can of worms. Pay and compensation for athletes is obviously a major piece of this equation. And as you said, many athletes can't sustain being a full-time athlete. Do you feel like there's a world where if some of these things can be sorted out and we can develop rosters that are more comprehensive and highlight individuals beyond their physical does pay follow? Is there a way to compensate athletes more if some of these other bigger issues are solved?", "token_estimate": 134, "speakers": ["Cole Heilborn"], "start_timestamp": "00:57:02", "end_timestamp": "00:57:02", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "0aa77659-15b8-4ebc-9f40-d4a0465e42d5", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 28, "content": "Lindsay Rogers (00:57:40): Yes, I think so. I want to believe yes, very much so, just because I've seen some pretty rough things happen to athletes unexpectedly. Or if a female athlete has a child, their pay is docked almost immediately, which those kinds of things are a little bit rough. And so I do think there's a world in which the athlete roster is curated in a very thoughtful way where maybe it's smaller, it might be less robust in terms of the breadth of the actual roster, but it's deeper in terms of who these people are, what they're doing for your brand, how much support they're getting on this kind of personal professional growth standpoint. And when you have a roster that sticks around for a little bit longer, it's less expensive for the brands as well. I mean, again, I keep bringing up Red Bull because they have a very, very different model where they're very much churning through athletes, but they're driven by their media house too. (00:58:46): So that's a different model all the way around. But when you're looking at traditional brands in the outdoor industry, I think there is a world in which they have fewer athletes, they support them more holistically, and they have a longer lifespan at the company. And that might mean there might be fewer athletes supported out there, but they're supported in a deeper, richer way. So yeah, I mean, I think financially it's a question of these athletes don't typically live a very expensive life. They're traveling a lot, and that typically gets paid for by the brands they don't live. They're out doing their exciting thing with the equipment that they use, but they're not living like a very lavish New York City lifestyle or anything. So the pay, generally speaking feels like it's quite low. It is in line with the lives that they live. But I think the athletes, it's also incumbent on them to say, here's what I need. (00:59:47): And they have to know what their budget is. They have to again, be a smart enough savvy enough business person to say to the brand, I need this to live. Here's my budget. You can look at it. Here's transparency into what my living expenses are. Here's the support I need from you to make it sustainable. And then also looking at what are their other income sources. So I don't think it's fair for an athlete to lean a hundred percent on one brand because it's unrealistic. And I think there's going to be a natural evolution of that athlete evolving out of the sport eventually. So for the athlete, I think it's really smart to say, okay, how do I diversify myself, my income streams to say maybe I'm doing some speaking engagements in non-endemic places like Meta or Novartis or somewhere where they are looking outside of the industry to bring in some income. So again, I think there's responsibility on both parties, there's the brand to pay them enough to be able to sustain a lifestyle, but it's also the athletes have to be realistic and say, I've got to diversify my income stream so I'm not holistically dependent on that one brand", "token_estimate": 762, "speakers": ["Lindsay Rogers"], "start_timestamp": "00:57:40", "end_timestamp": "00:57:40", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "5004655e-95ac-4d8e-b761-c420ce803787", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 29, "content": "Cole Heilborn (01:01:02): We've talked about a lot. Is there anything that we haven't covered that you want to mention?\n\nLindsay Rogers (01:01:08): Oh gosh, we have covered a lot. Let's see. I think the only thing that I would say is that athletes have a huge opportunity right now because I think there's so much focus on sport in the mainstream, again, with all the trends we talked about a while ago in terms of focus on winning sports and a lot of money being funneled into that world and all these breakpoint and formula on all these things coming out on Netflix. And so I think they have an opportunity right now to really say, I'm here. I'm here in a bigger, deeper, richer way. I'm going to give you something more than just me climbing a mountain and look at themselves as someone who is going to help someone else experience something new and exciting and look at themselves as a business. And how do I kind of elevate my business beyond the confines of sport? Because we have so many lights shining on sport right now, and so many lights shining on athletes, the Olympics are about to happen, which always gets people very excited about athletes no matter what sport you're in. And so I think it's a great time to be an athlete, and I think it's an exciting time to broaden your perspective on what's possible.\n\nCole Heilborn (01:02:33): Amazing to send us home. What questions are you asking yourself these days? Are there any big questions that you're, I mean, other than maybe what we've discussed, is there anything that you are thinking about that you want to share with us that maybe you haven't quite figured out yet? Or what keeps you up at night?", "token_estimate": 417, "speakers": ["Cole Heilborn", "Lindsay Rogers"], "start_timestamp": "01:01:02", "end_timestamp": "01:02:33", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "fa9a90d4-832b-4d31-9e6a-c728db946f2a", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 30, "content": "Lindsay Rogers (01:02:52): What keeps me up at night? How to keep my kids healthy, happy? No, I would say it's interesting. Speaking of kids, I do think it's sort of interesting me working in sport and with athletes and watching kids grow up and be involved in sports and those who choose to be involved in sports and not, I'm involved in sports. It is really fascinating as a parent to watch the impact of these athletes on my kids. They're watching these Netflix series, they're getting so excited. And so I think when I work with these athletes, what I'm thinking of is like, do you have any idea who are your impacting right now? These people are watching you and you are going to impact decisions they make in their future, meaning my kids. And so yeah, I think questions for me are just how do I get these athletes to say yes to this up so exciting For me personally, I love it and I see the impact they can have. It's dramatic and it's huge and it's meaningful. So that's what I'll leave you with. Yeah,\n\nCole Heilborn (01:03:58): I think one of the most special things about going to any sort of event, any sort of bike or ski event is whenever there's an athlete signing and whenever the kids just flock the table and they're decked out in the jersey number or whatever it is, and they're just so stoked to interact with that athlete and just the chance to say hi and get an autograph and maybe get a picture means the world to 'em.\n\nLindsay Rogers (01:04:22): It means the world\n\nCole Heilborn (01:04:25): When you consider what athletes are doing and when you consider what else we could be doing to help athletes, it seems like there's so many different ways we could do it. So it's encouraging to hear that you're out there spreading this message, trying to take a more holistic approach to athlete programs.", "token_estimate": 456, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "01:02:52", "end_timestamp": "01:04:25", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "34b99682-ee06-498a-bb31-7cfa649406a8", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 31, "content": "Lindsay Rogers (01:04:42): Yeah, no, thank you. I love it. I'm super excited. I love what I do, and I love the reaction we get from athletes. It's so fulfilling to me personally, and so cool to see these athletes all of a sudden open up this flower of like, wow, there's so much more I could be doing. There's so much more I could be experiencing and giving to other people. They'd never thought about themselves in that way, in a way where, wow, I can really have a very positive dramatic impact on these people who are watching me and they're watching me no matter what. So why don't I have this positive impact as soon as they see themselves with that ability. Oh man. It's like the lights go on. It's so cool.\n\nCole Heilborn (01:05:28): Lindsay, if folks want to follow along with you, if they want to connect and ask you more questions, where can they find you?\n\nLindsay Rogers (01:05:33): Yeah, so the website is raw strategy.net. Couldn't find that. Dot com. It's too expensive. And then, yeah, on Instagram, we're at raw strategy and we're in the midst of a crazy launch for Olympic and Paralympic athletes for a big program for the Olympics, for Paris. So spread the word everyone. But yeah, that's where you can find us.\n\nCole Heilborn (01:05:57): Amazing. Well, Lindsay, thanks for taking the time. I appreciate you sharing. I hope you have a greatness of your day.\n\nLindsay Rogers (01:06:02): Thanks for having me.\n\nCole Heilborn (01:06:03): Alright, bye. Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple.", "token_estimate": 402, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "01:04:42", "end_timestamp": "01:06:03", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "deaba35d-14e7-45d5-8c03-9bf2bd812758", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 0, "content": "Niclas Bornling (00:00:00): What happened? These brands just completely missed out on the cultural switch or the change in consumer landscape that happened around 2010, 2015 or something like that. What we're seeing today in the outdoor world is comparable to what happened at that point, and that's a little bit of a doom and gloom as well, but it also spells huge opportunity.\n\nCole Heilborn (00:00:23): Welcome to the Backcountry Marketing podcast. I'm your host Cole Heilborn. On this podcast, you'll hear from leaders in the outdoor marketing industry discuss the gritty details of their work, as well as the latest challenges and lessons that are learning along the way. If you want to hone your craft and become a stronger marketer than this podcast is for you. This podcast is produced by Portside Productions, an outdoor film production company based in the Pacific Northwest. If you work at a brand or agency in the outdoor industry that needs help bringing a video project to life, head over to portside pro.com and send us an email we'd love to help.\n\nCole Heilborn (00:00:56): Welcome to the Backcountry Marketing podcast. Today I'm sitting down with Niclas Bornling. He is an outdoor veteran, been in the industry for 25 plus years. Niclas, you spent sounds like about 10 years over in France and you've spent the last 10 years or so here in the US working for a number of US brands, Salomon, Black Diamond, and a number of others. Niclas, welcome to the show.\n\nNiclas Bornling (00:01:16): Thanks, Cole. Exciting. Looking forward to it.", "token_estimate": 388, "speakers": ["Niclas Bornling", "Cole Heilborn"], "start_timestamp": "00:00:00", "end_timestamp": "00:01:16", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "0a87a1fc-7bbe-46a9-8fc3-a2d199c8198a", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 1, "content": "Cole Heilborn (00:01:19): Yeah, I am looking forward to this as well. This is a couple years in the making. I feel that we tried to pull something together a little bit ago and here we are ready to record and ready to sit down and dive in. We've got a fun conversation. I dunno if fun is the right word. We have a timely conversation, I think scheduled for today. We've been on a bit of a doom and gloom click with the episodes we've been rolling out over the last few weeks, and that isn't intentional. It just seems to be, this seems to be what's on people's minds. We recently put out an episode with Josh Weichand from Rumpl talking about this forest fire rolling through the industry. That was the analogy that he used. Before that we had an episode with Matt Powell talking about just some of the economic challenges that the industry has. (00:02:07): And Niclas, we're going to kind of continue that trend a little bit, but talk about the challenges the industry faces from a different perspective, looking a little bit back in time to hopefully forecast and help us prepare for the future. And Niclas, I think you said it best, when we connected for an intro call a couple of weeks ago, you said, you asked me a question. You said, Cole, what do the brands, Quicksilver, DC shoes, Roxy and Volcom all have in common? And you said, I didn't know the answer and I think you helped me out. And you said they're brands that were once juggernauts and who knows where they are today, you said we should be paying attention to this lesson that happened in the early two thousands, 2000 tens. And so with that, Niclas, I'd love if you could give us an opening statement on what you've got kicking around.", "token_estimate": 426, "speakers": ["Cole Heilborn"], "start_timestamp": "00:01:19", "end_timestamp": "00:01:19", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "ec6aa9e8-c842-4ff9-861d-e7f9fbd63827", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 2, "content": "Niclas Bornling (00:02:55): Well, the comparison that I am making and the reason why I asked you what happened to Volcom, what happened to dc, Quicksilver, Roxy, Billabong, rip Curl, and the list is long, right? I mean, they were incredibly powerful at the time. They were big brands, they were driving a lot of revenue and they were intertwined with at the time a very culturally relevant trend that is happening around and then huge brand stores on the middle of Manhattan. And I'm thinking about the Quick Civil Roxy store and all that kind of stuff to nothing, absolutely nothing today. And there is something to be learned from what happened there. And whatever I'm going to say about that is obviously my own sort of learnings and reflections and trying to make sense of the outdoor landscape in general and also as an extension, athletics and sports because it's all sort of intertwined and you can add to that fashion and lifestyle and all that stuff. (00:04:08): What happened in the way that I look at it is these brands just completely missed out on the cultural switch or the change in consumer landscape that happened around 2010, 2015 or something like that. And I think that what we're seeing today in the outdoor world is comparable to what happened at that point. And that's a little bit of a doom and gloom as well. But it also spells huge opportunity and we're going to get into it and if you want me to continue digging into just that one, but really there is a learning from what happened to billion dollar brands that were right in the center of culture at the time to being completely not part of culture today and what happened to outdoor brands and what outdoor brands are going through right now in outdoor retail.\n\nCole Heilborn (00:05:07): Well, yeah, sounds like we've got a lot to dive into. This is a hefty idea, hefty episode. Before we do, could you give us a quick little background on yourself, where you've been over the last 20 years and some of the brands that you've worked with?", "token_estimate": 505, "speakers": ["Niclas Bornling", "Cole Heilborn"], "start_timestamp": "00:02:55", "end_timestamp": "00:05:07", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "1e4c42b7-c59d-4a68-9da2-e95513f83019", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 3, "content": "Niclas Bornling (00:05:24): Yeah, sure. I think I'm probably getting a little bit on the old side right now because when I'm going back in time, I started realizing that I started in the industry a long time ago, but I am originally from Sweden. I was trying to be an athlete at one point and that led me on to working at an ad agency in the beginning and then got really lucky, got picked up by accident. I tend to think by Salomon in a local marketing role. And that set off the most informative learning experience, pivotal to me in my career. What I learned during that period of time at Salomon, which was 15 years, I have to thank for pretty much everything else that comes afterwards, even including meeting my wife. Actually, this is at a point of time when people started racing in the outdoors, actually going from A to Z the fastest you could. (00:06:39): This is when Salomon was almost the world global leader in inline skating. Believe it or not. It was a very creative period of time. It's a lot of stuff happened in that time that today has huge ramifications on brands that either made it to the next level or stayed where they were and potentially have almost started to sort of disappear. And after having sort of done the executional nature of marketing locally, I wanted to be working at HQ and got a transfer to one of the most beautiful places on the planet, which is right in the center of the French Alps within a striking distance of a hundred ski resorts and the most famous one being Shani, which is 45 minutes from Nessy where Salomon's global headquarters is based and Nessy is right next to the Swiss border and an hour from Italy and you name it, it's paradise really, which I spent 10 years at. (00:07:50): And about seven of those years at the end I got lucky again and got picked up so that I could run the Salomon Global brand for about seven years. Incredible amount of learning experiences from that too. And during that period of time, I met my wife at a sales meeting in Germany. She is American from Portland, Oregon. And eventually that led us to deciding to move to the US and create a family and all that stuff. And I got recruited by black diamond equipment in Salt Lake City where I spent four years just the VP of marketing, but then eventually Keen Footwear brought me up to Portland, which was sort of like coming home for the family. My wife is from Portland and this is where most of our relatives and friends live today. But a good place to be if you're in sports and outdoor. I live really almost within walking distance to both Nike and Columbia. And now there isn't an athletic brand or outdoor brand that has an office somewhere in Portland. That's a little bit about my background.", "token_estimate": 685, "speakers": ["Niclas Bornling"], "start_timestamp": "00:05:24", "end_timestamp": "00:05:24", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "8156bbab-716c-43b6-871a-d18c3494dad8", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 4, "content": "Cole Heilborn (00:09:08): Yeah, fascinating. You mentioned that you had this realization or you were working with a brand and you were tasked or you thought, Hey, maybe I should map the industry. Maybe I should try to have a better understanding, a holistic understanding of where our industry is going. And at what point did you realize maybe it was a good decision to look backwards in time to try to understand what's going to happen in the future or what could happen in the future? And tell me about that moment and what you started to realize as you started to look backwards and look at some of these large brands like Quicksilver and DC shoes and started to realize what lessons could they teach us?", "token_estimate": 177, "speakers": ["Cole Heilborn"], "start_timestamp": "00:09:08", "end_timestamp": "00:09:08", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "298db261-ffbe-4e05-90c4-af1a2911ab78", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 5, "content": "Niclas Bornling (00:09:45): Well, one of the things you start realizing when you've been around and worked long enough and had long enough of a career is that nothing is static and nothing is forever. The only thing that we can say for true, for sure is that the pendulum always swings back. And this happens everywhere all the time. When you start realizing that the pendulum will always swing back and forth, you start realizing that the outer space is not going to be static. There is going to be things that come and go, and that's the only thing that we can say for certain. (00:10:35): We can also say for certain that younger generations will be looking backwards for inspiration. We'll be looking backwards for putting an imprint on themselves in culture, but making it theirs. And that's a really important learning call because you look at Gen Z, gen Y today and you look at their fascination for brands traditional, I mean traditional brands in the outdoor space such as the North Face, such as Patagonia, such as Salomon and a bunch of other brands. But you also start understanding that they just don't want to have exactly how it was back in the day. They want to make it theirs. When the outer industry, the apparel outer industry was really sort of forming and shaping to what it would become today, it was in the nineties. And so a Gen Z's fascination with outdoor is in a larger context, gen Z's fascination with the nineties in general. (00:11:42): And that's really important to know because that makes it even more fickle for certain that younger generations will not stay fixated on a period of time. They will move on. So there's going to come a time, and lots of us have thought that that would've been over already a couple of years ago, which has proved to be wrong. There's still a fascination with technical outdoor apparel, authentic brands from back in the day, but it will taper off. And I would even venture out saying that it has already started tapering off. That's one of the things that makes you go, what's going to happen to this thing? Is the bubble going to get burst? And what happens in that case to a lot of brands that have been enjoying this uptick in demand. So there's one of the learnings, and as you hear, I will always come back to understanding the consumer landscape, which belongs to just a very simple, almost generic way of defining a brand's go-to-market. Market or just marketing and brand and consumer or product plan, which is answering three questions. You have to be able to answer the question, who am I targeting? (00:13:22): And by the way, let's just not use the word targeting. I'm sorry, all listeners, it's such a boring military reference. Who is my audience? Who am I speaking to? Who am I telling stories to? And then you move on from there to answer the question, what am I offering? And that's an important one because you cannot answer the question, what am I offering? If you haven't been very clear with your who first you just can't do it, the answer, the answer is, what's the story that I'm offering you? What's the equity that I am offering you? So it's a who, what and how. Super simple, very easy. It doesn't sound very advanced, but the thing is that you'll find 90% of your answers by really digging super deep into that and you start realizing that if I don't have a really good understanding of my audience, the other things will probably be inaccurate. There's lots of examples of companies and people that've gotten lucky by just being right in time. Exactly right. But that's not really a strategy, that's not really a model that you can replicate. So", "token_estimate": 910, "speakers": ["Niclas Bornling"], "start_timestamp": "00:09:45", "end_timestamp": "00:09:45", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "6150cb61-474b-46ff-acf0-9322fa795edd", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 6, "content": "Cole Heilborn (00:14:42): I mean, what happened to those big brands back in the day? I mean, I think I was looking it up in Quicksilver at one point, at its largest was a $2 billion brand. And if you can, yeah, what happened? Why did they disappear?\n\nNiclas Bornling (00:14:56): Well, what didn't happen is that participation in action sports did not decrease, which is really important because you could pretty much just sort of track this down to, well, there were much less people that were skateboarding and snowboarding and surfing and riding BMX bikes and whatnot, but there is more people today as far as I know at least that are snowboarding, skateboarding and surfing than has ever been before. So it wasn't a lack of interest in the practice. It wasn't a lack of interest in surfing and skiing and snowboarding. It was a change of culture. (00:15:43): The culture that was portrayed through these brands became kind of irrelevant to the larger culture of that generation of younger generations that were targeted. You asked Gen Z about climate anxiety, 86% says that they have anxiety about the climate, and none of these things that became culturally relevant were part of the narrative of any of these brands any longer. They just felt like they were stuck in a time that they couldn't really get out of. The other thing that you started seeing is that the targeted audience or the audiences that we were going after at the time became more and more curators. They were picking and choosing stuff that they thought would be relevant to them and their culture. They would pick a piece from a fashion brand and they would mix that with vintage clothing found in a secondhand store. They just did not really conform to the codes that you would have to be dressed from top to toe in action. Sports brands. It just wasn't interesting to them any longer. They would still go snowboarding, skiing and surfing and skateboarding, but they would look completely different. And that was just a miss by these brands and fail to understand that the consumer landscape had shifted drastically, (00:17:33): And that is really why almost a whole industry, because it's not just these brands, it's also a lot of wholesale retail that disappeared in the same time.", "token_estimate": 565, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "00:14:42", "end_timestamp": "00:14:56", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "edd5379d-f5f8-4bdb-b214-6ea224f63a09", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 7, "content": "Cole Heilborn (00:17:48): What changed? Did the brand stay true to its course and the consumers changed or evolved, or did the brand deviate expecting that the consumers would follow the deviation and they didn't?\n\nNiclas Bornling (00:18:02): No.\n\nCole Heilborn (00:18:03): Or is it a combination of those two?\n\nNiclas Bornling (00:18:04): No, I think the brands stayed very true to what they thought was the core would probably in many cases could be yourself that is working inside the brand. I don't think that's it. I don't think they lost the course in general. I think they just lost touch with their audiences\n\nCole Heilborn (00:18:33): Because the audience was changing. It was evolving. So what does that mean for us today? Is that a story that you see being written currently?\n\nNiclas Bornling (00:18:42): Yeah, there are signs, pretty strong signs that we're seeing about the same thing happening in the outdoor space as well.\n\nCole Heilborn (00:18:53): And how so? What are you seeing?", "token_estimate": 250, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "00:17:48", "end_timestamp": "00:18:53", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "626328d9-3788-40cd-99af-0e29f9fb08ca", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 8, "content": "Niclas Bornling (00:18:55): Well, it's enough listening to Matt Powell's podcast that you had on here to understand that there is a lot of the numbers, the financials, the revenue, and the amount of retailers and brands that are out there that are not showing very good signs right now, they're not healthy at all. I mean, VF has obviously reported all kinds of pretty negative quarterly reports lately, the flagship ran the North Face that used to pretty much drive. The VF group is no longer growing, if anything going backwards, and I'm not even mentioning Vans, which doesn't really sit in the outdoor space, but sits in the action sports space also going backwards, also tanking, and you listen to the layoffs that are happening constantly within the industry, REI, laying off people, Columbia Sportswear, laying off people, profit warnings to the left and to the right. So the science, so the metrics have not been favorable to a lot of actors in the outdoor space. (00:20:20): Wholesalers declaring bankruptcy. I hear it every single day, so what's happening? What's going on? Yes, there are factual things. We know that the pandemic inflated the business to a level that wasn't realistic, and that was the only place people could go and rewarding yourself with a pair of new hiking boots or a new jacket or whatever. It was a nice thing to do. It inflated demand to a degree that was completely out of proportion. Brands started producing and making inventory levels that were insane. Wholesalers thought this would probably last and it didn't. Right? So that's one of the things that we know for certain that has happened, but what also happened in the pandemic is that it opened up the doors for an audience of people that had previously not been part of the outdoor landscape. I mean, you went to any of the trade shows and you would see the same people, middle-aged, white guy walking the horse, sharing experiences, sharing insights and understanding of the space, but the people that found themselves spending time outdoors were new audience of people, people that had previously not been accounted for at all, and they came in with a different perspective on what is an outdoor practice. (00:22:02): I mean, for us, it used to be I ski at least 50 days a year. I sport climb, I climb indoors, I run trail run and hike and stuff like that, and I go the Pacific Rim Trail, like these were the standards and the definitions of an outdoor user. Now people are coming in and they may be birdwatching. (00:22:30): It is become a real practice done by a lot of people that are still not really accounted for in the outdoor space, just taking a walk with the dog, just being outside in the forest, breathing the air from the trees were becoming real things done by a lot of people that the outdoor industry had no idea how to speak to, had no idea how to tell stories to because it just wasn't us, right? It's hard to relate to and with the influx of these people, and you combine that with core, that opened up the gates for an audience of urban dwelling audiences with very different preferences with very different cultural references. Overall, it is now changing the outdoor consumer landscape to a degree that brands and retailers have been unable to most part, I would say, because there are brands out there that are showing very good signs of really understanding these cultural changes and trends that are going on, but a lot of them, us, I should say, have not, and it is not easy, I can tell you because you have then brands that have been around for 25, 50 years spending time with yourself and the people that are part of your community and sharing interest and building community that way now have to completely shift their mind to what's an outdoor consumer in an urban landscape. (00:24:28): How are they thinking? What are their wants and needs? What are their habits and practices? How are they looking at the world? How do we tell stories to those people when you're not part of it? Not easy. It's actually really tricky. How do we meet their wants and needs in terms of product? They're not looking for stuff that they can climb the fourteeners with or go to Himalayas with or do any of the core practices that we have. They're looking for apparel and footwear that solves for very different needs and wants, right? So there is a fundamental change in the consumer landscape out there right now and combine that with the pendulum all with swings. GOP core will not stay here forever. Combine that with the after effects of the pandemic. You have pretty much a perfect storm currently.", "token_estimate": 1153, "speakers": ["Niclas Bornling"], "start_timestamp": "00:18:55", "end_timestamp": "00:18:55", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "42ec8297-bd76-4f35-a05f-40a0fccb4c04", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 9, "content": "Cole Heilborn (00:25:40): That's the analogy I was drawing before you said it. It seems like it's a perfect storm of variables and of kind of tectonic forces at play. If you had to pick one between the audience landscape, changing the go core trend, maybe fizzling out at some point, and then just the general pendulum swing, which one, are they all three equal in terms of their impact or is there one that feels the most potent? Yeah,\n\nNiclas Bornling (00:26:12): I mean the pendulum always swings, so it'll swing back at one point when I don't know, but it will. So I would put that one aside and if anyone from a brand side and from retail right now is listening, I'm just going to tell you guys that do not hinge your future on core continuing because it will not, that's for sure. There will be a new look back on something else will drive things right then the nineties cannot last forever. So that's it.\n\nCole Heilborn (00:26:48): Well, I think you said that a lot of brands are seeing massive revenue growth in China and Asia go core trends in those countries, and that's maybe bolstering the revenue numbers for those brands, but that's not going to last forever.\n\nNiclas Bornling (00:27:10): Maybe not. That's a tricky one for me to answer honestly, because definitely not a specialist in the Asian markets. I mean, I know, let's be clear about who we're speaking primarily about China because the uptick of brands and American, Canadian, European brands that are today growing pretty quickly in China, there are many of them. Will it last? Will it not last? Well, I mean if you think that it's going to last because it's a fashion expression, then that would not be a very good thing to hinge your future on if you think that the outdoor user base is growing as well and creating a solid foundation for an outdoor brand to build on for the next 25 years, which could be the case. I don't think the growth of China can purely be explained that outdoor brands are being positioned as luxury, technical fashion. I don't think it's that simple. I think there is also an uptick of outdoor practitioners in China. How big that will be. I do not know.", "token_estimate": 539, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "00:25:40", "end_timestamp": "00:27:10", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "fedf55ba-3fff-409d-8717-5fd9efe742c4", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 10, "content": "Cole Heilborn (00:28:30): Gotcha. But I guess back to my original question before I interrupted you, it sounds like the audience change is really the primary force there at play that\n\nNiclas Bornling (00:28:42): You see. I think so. Yeah, I think so. And I think it's probably the only one. I mean if you want to be looking at positively having a positive outlook on the future, that's the one piece that you can do something about.\n\nCole Heilborn (00:28:58): You can figure out where those people are\n\nNiclas Bornling (00:29:00): And you can start telling stories that are relevant to them. You can start offering solutions that are relevant to them that can be done.\n\nCole Heilborn (00:29:10): How long, if you had to guess or if you have any science around this, how long does it take for an audience landscape to shift? How long did it take for the audience to change for those Quicksilver and other brands? Was that a 10 year shift, five years? Is that a repeatable cycle that we can count on?\n\nNiclas Bornling (00:29:30): Yeah.\n\nCole Heilborn (00:29:30): Is that a generational thing?\n\nNiclas Bornling (00:29:32): I think so. I think skateboarding is probably one of the best isolated spaces and practices to look at in general. And it seems like skateboarding has been following this seven year rule over time that it's like it takes about seven years for it to sort of simmer and go back to the core. And then for about seven years it'll start affecting and influencing the mass and much bigger audiences and then it'll about seven years. So I don't know if that exact same time period will be transferable to other spaces overall. But I don't think you're talking, you don't talk less than five, that's for sure. I don't think you talk more than 10 either. So there you go. Somewhere right in the middle, about seven years for the pendulum to swing.", "token_estimate": 465, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "00:28:30", "end_timestamp": "00:29:32", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "2e30f371-2070-4a85-91da-6f34d18ac1a6", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 11, "content": "Cole Heilborn (00:30:33): And you'd mentioned in our intro call that maybe part of this, I guess I think about, I used the word tectonic forces earlier and I think about earthquakes and I think about seismologists and scientists put sensors out into the earth to detect, to detect earthquakes before they actually hit. And I'm curious, what are ways that we can be predicting what is changing? What are ways that we can be listening better as an industry? What are tools that you see working or could be used to predict where these things are going? I mean, it sounds like a lot of this stuff you have to kind of have a front row seat in culture and be listening and be observing, but are there metrics or are there things that we can be using? Are there sensors that we can be using to track this stuff rather than just relying on a gut feel?\n\nNiclas Bornling (00:31:38): Yes, and honestly it's not that complicated and I'm not going to say you've got to be paying for the best consumer insights reports that exist and stuff like that. It is who you surround yourself with. And that is the key to the whole thing goal, right? Because as I said, you walk the halls of, or ispo, you would pretty much see an incredibly homogenous crew of people that looked exactly like we did, right about the same age living and that's super dangerous. So you have to start employing people that are different than you are. And we get back to diversity and inclusivity. It is more than a social justice. It's actually a survival instinct that you should be employing or a survival tactic that you should be putting into place. It is hugely important that you employ people or you work with people that are diverse and different than you are, right? You've got to have that person that sits in the room that has a very different frame of reference and you have to listen. And the listening part is also trickier because biases are real. Then you just want hear what you want to hear here. Do not just employ and bring them close to you, but really listen,", "token_estimate": 510, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "00:30:33", "end_timestamp": "00:31:38", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "74584070-10e4-4752-8eb8-7711523083d5", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 12, "content": "Cole Heilborn (00:33:26): If you had to, I don't know, give me a good, a better, decent or worst prediction of where things could go, possibilities, depending on the industry's ability to listen and evolve. What are those possible routes the industry could take?\n\nNiclas Bornling (00:33:47): I think it's very real that within the next five years there will be brands disappearing. I don't\n\nCole Heilborn (00:33:57): And are you talking like some of\n\nNiclas Bornling (00:33:59): The juggernauts of the industry? No, I don't think so. The juggernauts will have enough finances, resources to shift and swing and learn, and they are probably surrounding themselves right now with people that are looking at the world very differently. I don't think so. I think we're talking about midsize brands, midsize, specifically midsize. I'm actually less concerned about smaller ones. I think smaller ones can pivot quicker and adjust, and I think smaller ones are younger in general and young is good when it comes to this. I think the mid-sized ones, the ones that are sort of like, I dunno, 50 to $150 million are the ones that are mostly in danger currently. (00:34:54): And that is not just brands in the sense that it's a producer of goods, it's also retail that is on the line here. So it's a very real possibility that we'll see quite a few of the actors falling off as we move on here in the next two to three, four years or something like that. And I think that it may have already happened faster if it wasn't for the uptick of revenue generated from China. I think that has probably saved quite a few of them. I think there is a bunch of smart people in this industry that knows exactly what we're talking about right now, Cole, that have understood this for quite some time, that are building an infrastructure internal organization that is already there, that is already answering to a bunch of these things. I know personally that there's some very good people out there that knows exactly what to do. I think that if you look at a classical outdoor apparel brand and you look at sort of the offering and you look at the stories that are being told traditionally it's going to 80% or whatever technical apparel solving for a specific need, whatever that be, skiing back country skiing, front side skiing, climbing, mountaineering, hiking, et cetera. The solving for these issues has been about 80% of the offer and hence 80% of the stories that have been put out there. (00:37:00): I think the future looks different than that. And by the way, I forgot to mention that the other 20% has probably been referred to as lifestyle that will no longer be a recipe for success in the future. If anything, and you want to be drastic, it may even flip to 80% solving for practices that are non-core for a functional life in general, people that are asking for functional performance apparel but not functional for climbing mountains, not functional for skiing, functional for life instead. And then 20% of the offer and stories will be designed for solving core needs, core problems, core things. That's probably a little bit revolutionary. I don't know if a lot of people will agree with me on that one, but I truly believe that younger audiences are looking for smaller wardrobes, smaller closets, less stuff, better stuff that lasts longer, but maybe even more importantly than lasts longer solves for a big majority of their daily how to wear and what to wear needs. (00:38:39): And if you want to ask me my personal opinion, that's exactly where I stand. I will be looking at the materials and the fibers that have been used going into production of stuff. I'm always eager to listen to innovation that is happening in this space, but if you ask me what can I do right now to limit the harmful and negative effects on our planet, it is to have a smaller closet that is much more productive. I have less stuff, but the stuff that I have I can wear on an everyday basis and also doing my outdoor stuff at the same time.", "token_estimate": 1004, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "00:33:26", "end_timestamp": "00:33:59", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "a173be05-a495-4d20-817b-759b2e675145", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 13, "content": "Cole Heilborn (00:39:26): So back in the Quicksilver days, 2000 tens users were changing their wardrobes. They were changing what brands they wanted to represent, what they wanted to wear. You mentioned that people were going to thrift stores and piecing together wardrobes rather than representing one brand entirely and daily life. Is there a point though where maybe we're already here where it's no longer, I don't want to use the word fashionable, but it's no longer the taste of the audience to represent a brand. Is there a point where we don't want to have a logo slapped on our chest, we want something that's nondescript or doesn't have a logo or because we don't, I think you mentioned earlier, everyone wants to be unique. There seems to be this trend that you don't want to conform and in some ways some brands are anti, and so that draws people ironically to them as an establishment. But is there a point where we don't wear a brand because we don't want to be part of a culture. We want to be our own authentic independent selves. If that's a trend that continues or take stronger roots, how do brands adapt? Do we just start? Do they start hiding logos? (00:40:48): What's the recipe for success there?", "token_estimate": 305, "speakers": ["Cole Heilborn"], "start_timestamp": "00:39:26", "end_timestamp": "00:39:26", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "2a4f3e76-befe-4464-9789-a23b800cb22c", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 14, "content": "Niclas Bornling (00:40:50): I think what you're saying is super interesting goal, and I've thought about that a bunch too. I mean, the nineties was all about big freaking logos, right? Colorful in your face, very expressive. The codes were super expressive and hence brands that were living that were looking like that have been picked up back again and come to forefront now, I honestly don't think that that will last. And I think we've already started to see that it's becoming less and less relevant to be wearing big logos right in your face. I think individuality is being expressed slightly differently than having a big logo that is shining in your face. I used to work for a beautiful brand company called Houdini Sportswear for a few years, and we had this debate constantly because with DE, you can barely see the logos on the garment. They're tone in tone, they're small, they're sitting in places where it's not left chest and right shoulder. And there would be the people that said, we just need to make the logos more prevalent in your face, not tone in tone sitting bigger, et cetera. And there was a pushback from within the company that said, no, we don't want to do that because we don't think that that's our audience. (00:42:38): We don't think it's the future either. And I've left the company still remain an incredibly huge fan of it, but I am pretty sure that actually the people that were driving that point of view were correct. (00:42:52): I don't think the future, and I'm not saying the indefinite future, but the next 10 years is going to be about big logos. I think it's going to be less in your face just in general, more about yourself. And it's definitely not going to be the one brand uniform. It's going to be much more curated. I'll pick a piece from this brand, but then I'm going to pick a piece from a brand that it doesn't even belong in this space because I am going to show that I'm different. I'm going, I will not conform. And I love that. I mean younger generations, the rebellious attitude is just amazing. I wish I still had more of that left in me, but as long you go a little older, you sort of like soften up the edges a little bit as you go. But I am a hundred percent sure that that is going to be a trend goal. So what do you do? Well, you understand and you put your own point of view on what that means for your brand, right? You're not going to rewrite the purpose of existence of your brand every time a trend changes, but you can show by adjusting course a bit or launching a range of product that is slightly different and so on and so forth. (00:44:28): There's definitely ways of meeting that and it will all stem from you really understanding the audiences that you have to speak to.", "token_estimate": 687, "speakers": ["Niclas Bornling"], "start_timestamp": "00:40:50", "end_timestamp": "00:40:50", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "7d5d8f81-72a8-463b-ae54-a3b12156df54", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 15, "content": "Cole Heilborn (00:44:37): Well, and I guess that comes back to your three points, which is, yeah, I understand your audience, know what you're offering them and then find a way to tell 'em a story. Those are your three points, right? That I get those, right?\n\nNiclas Bornling (00:44:48): Sounds simple, doesn't Nicole?\n\nCole Heilborn (00:44:50): Yeah, sounds real simple, but I think I feel like the moral of the story with every episode I think we do on this show, everything sounds simple in theory and obviously execution and practice is significantly more difficult than the words, the theory behind it all. Where does this put us in terms of, it puts us the industry moving,", "token_estimate": 170, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "00:44:37", "end_timestamp": "00:44:50", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "deb719d9-34ab-4143-a3f4-50ad43df33f8", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 16, "content": "Niclas Bornling (00:45:10): It puts us right back to the one thing that will not go away. And it's to tell stories that are meaningful, that are relevant because at the end it's what we do. We either tell good stories, we tell bad stories, and with bad, I mean stories that aren't relevant or we do not tell stories. And I think there are ways in today's digital landscape to downplay the need of telling stories a little bit. But a majority of brands out there have to do and tell great stories as we move on because it's the one thing that will not go away from us human beings. And it is the one thing that almost makes us human to a degree. (00:46:14): And the story isn't something or brand storytelling, which is something that I don't really, it should, I mean it should not sit within the marketing department. It's not owned by the marketing department. It's a company wide thing. Every node that has any kind of visibility to the outside world is part of your story. How your human resource HR people interact with employees or hiring a new person is a huge component. Your customer service people, how they interact with the world, every single component, your sales teams be that wholesale sales teams or e-commerce, sales teams or stuff. Everything is a story. And if you remember Cole, the definition of a brand is basically the sum of the stories that people remember about you. (00:47:24): So in a sense, you don't even own your own brand. The brand is owned by the people that is part of your community that you speak to overall. And all that we're trying to do is to nudge them in a certain direction so that they start thinking about you in the way that we would like them to think about us. So I will never, ever budge from my core belief that crafting and telling culturally relevant stories that are powerful is the essence of what we do. When you can prove that you can connect and you have a book and the book has a title, which is pretty much this foundation for your storytelling of your company and your brand, and then it has chapters, but the chapter, this indefinite amount of chapters and every time we interact, we open a book to a new chapter and we continue doing that over and over again. (00:48:35): And you also know that really what made us the dominant species of this planet was our capacity and capability of organizing ourselves and transferring knowledge between ourselves so that we can organize ourselves in big groups was our capability of telling stories. It is how we have transferred knowledge since day one and we will continue doing so. It will never go away, in my opinion, the day that goes away. I don't even want to be around any longer right now. So that means when the stories that connect with your audience, it's the day to start amplifying hard. But I would not suggest that anybody amplifies until you've gotten to a point that you know have a story and a concept overall that connects to a very specific audience. And the more narrow and the more niche that audience is, the better it is. Because mass will always look into the smaller niches to smaller cultures and be interested and try to figure out what's going on there and want to be part of it. So don't be afraid. Don't be afraid to address the few. It makes it intriguing and powerful and interesting. And then you push the amplification buttons and that's in how", "token_estimate": 846, "speakers": ["Niclas Bornling"], "start_timestamp": "00:45:10", "end_timestamp": "00:45:10", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "d8a581a1-c45a-4fc5-89a9-2d6a8146f3fa", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 17, "content": "Cole Heilborn (00:50:12): I love what you said there. And so this is something that I think about a lot and something I've talked a little bit about, but I've been developing this idea when it comes to storytelling and the ability that stories have, and I, I'll run this by you, but you mentioned tell a story to a very specific audience. And when I look at the film production process and the steps and the decisions that have to be made in order to tell a story just through the video medium, obviously there's so many other ways you can tell stories, but in that world, the world in which I live, I'm always amazed at one, the amount of decisions that have to be made in terms of really nitty gritty details that you don't think about locations, time of day, the character that we're casting or the customer or the ambassador that we're choosing to be in this spot, thinking about things like wardrobe, thinking about what are the activities that are being presented on screen? (00:51:20): And I'm always amazed how each of those decisions has the opportunity to speak to a very particular person. The person that we're casting the things that they're wearing, the color of their skin, the language that they speak or their accent all have the ability to reflect someone else who exists in the world. And one of the questions we always ask new clients when we're working with them is like, well, who is our audience? Who are we trying to reach? Who are we trying to share this message with or connect with or whatever the goal is? And oftentimes the answer to that question is always incredibly vague. It's usually like, well, we're trying to reach a millennial. (00:52:06): And I'm always amazed at just how much missed opportunity there is because while storytelling feels like it can be this very lofty and ambiguous, like emotionally driven a methodology that doesn't have any science behind it, while that can be true, it also has the ability to surgically reflect or represent a very specific population or demographic or a user. And the choices that you make on set or leading up to set are all ways to reflect that user, that person. And so I love this idea of know who you're talking to, but really know them, know what drives them, know insights about them. And those are all tools that you can then incorporate into, in our case, into storytelling through the video medium. And it's a missed opportunity. I don't see many of our clients doing that. And it's unfortunate because you could see tremendous results. (00:53:09): There was this political ad I saw a couple few years ago and it was this Latino woman running, I don't remember what she was running for senator, a state senate. And it was so clear who her audience was because she knew her wardrobe. There was inside joke, she was wearing high heels and she was waiting for the train. And I don't remember what exactly happened, but there's this moment where she takes off her heels to walk across the grate onto the train, and it's this one five second moment, but it connected so well with her audience because you look at the comments and everyone's like, oh, I do that. I have to take off my heels or I have to do this thing. And it just showed so well how well she knew who her audience was. And you don't know the value of what is the value of knowing that about your audience? Well, you can see it in the comments because people are like, she knows me, she is me. I am her. I'm going to vote for this woman. And so that's honestly the best example that I've ever seen of a commercial or a story that a brand or politician has put out there who really knows who their audience", "token_estimate": 914, "speakers": ["Cole Heilborn"], "start_timestamp": "00:50:12", "end_timestamp": "00:50:12", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "25125fe5-820f-43be-914d-98751eb0a902", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 18, "content": "Niclas Bornling (00:54:24): Is. It's everywhere. Cole, right? It doesn't belong to us marketers and brand people. If you realize that a brand is an accumulation of stories that lives in the minds of the people that you're speaking to, you start realizing pretty quickly that the idea of building a brand is something that is done all the time out there by all kinds of different people in different situations. And they may or may not even know that it's the case. And quite often the best work and the best stuff is happening when you don't even know that you're building a brand overall. But it will come down to you telling a story that is relevant to an audience of people. And if it's scales, it's because that story can sort of disseminate beyond afterwards. It's really hard to plan for the latter part of what I just said there, but it is not that difficult to plan for the first one. B sharp, right? B sharp, be niche, be very specific about who you're speaking to, show those signs and be clear about it because everybody will be interested in a brand that has a very strong cult following because there is the potential of scaling that afterwards.\n\nCole Heilborn (00:55:53): So if you moving forwards, what do you recommend? I mean, it sounds like the moral of this episode is know your audience, pay attention to your audience and realize that your audience might not be you.", "token_estimate": 347, "speakers": ["Niclas Bornling", "Cole Heilborn"], "start_timestamp": "00:54:24", "end_timestamp": "00:55:53", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "81023a81-74bc-495a-897b-b4c940861e7e", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 19, "content": "Niclas Bornling (00:56:06): Yes. I mean, at the end of the day, that summarizes what we do. And the warning to us that has worked in the art industry is that the world has changed. It has changed because of a lot of different things that has happened in larger culture. It's not just economical aspects that are affecting us today, but it is affected and changed the way that younger generations are thinking and how they're going to be thinking in the future. The pandemic was not just the virus, it was much more than that. It has changed us for generations to come. The way that we're looking at life, at recreation, at home, at work, as family, all of those things were affected by the pandemic. The war in Ukraine has had an enormous effect on the European countries and to an extent the us, but not as much. We are a little further away, but in Europe, it's right next to you. I mean, I'm from Sweden. We are basically practically bordering Russia. So it's there, the Baltic Ocean, Baltic seas just one step away from the war, and that affects how people think about the future. (00:57:52): So things have changed and it is a new reality that we're living in and that will affect the way that we tell stories and listen to stories overall. It will obviously affect how we make purchase decisions. There's no question about, but those are rational things at the end of the day, and people don't make rational decisions when it comes to buying outdoor gear. We make emotional decisions. We will let our heart and our gut guide us in the purchase decision. And when that decision is done and you're wearing the thing that you bought, now, you will rationalize your decision to the people around you. The world has changed forever, but we keep making emotional decisions, so that's stable.", "token_estimate": 448, "speakers": ["Niclas Bornling"], "start_timestamp": "00:56:06", "end_timestamp": "00:56:06", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "86d83e72-b6a6-44f6-b3c0-1853d2b66277", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 20, "content": "Cole Heilborn (00:58:49): Listen to the emotions and realize that what you're feeling might not be what others are feeling. I mentioned this before we started to record, but there's this quote, I can't remember who said it. It was some president, but he said, where you sit determines where you stand, and everyone has a different seat. Even though Niclas, you and I might be sitting next to each other in fairly adjacent seats in the same row, we each have our own different perspective, and that influences how we see the world and how we interact with it. And it's a complicated world. Everyone is complicated and multilayered and multifaceted.", "token_estimate": 162, "speakers": ["Cole Heilborn"], "start_timestamp": "00:58:49", "end_timestamp": "00:58:49", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "fd792801-903d-458a-ba3f-0e169d91dcc5", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 21, "content": "Niclas Bornling (00:59:25): Yes, so much. And it's what makes it interesting, right? It's fun. (00:59:34): I think that the best marketers, the best brand builders are in general, the people that are the most tuned in to other people. So I remember when I was at Solo in France, France has this amazing program during your college years, you have to do a year and a half of internship. It's long. So you can divide it and you'll divide it into two pieces. But most students will spend a year inside a company. During a year, you will become much more than an intern. You will become part of the company and you will be regarded as a normal employee after a while. But towards sort of the latter end of that period of time, I sometimes had intern students that would come to me and said, okay, what do you think I should study? (01:00:34): Should I do more of this kind of marketing or should I go and finance and whatever? And I'm like, if you want to be a great marketer, don't study marketing. Whatever you do, don't do that. Because the playbook of marketing is evolving pretty much every single day. And the playbook of marketing will be different from one company to another company anyway. So you're going to learn the playbook in the company that you get to, and then you're going to be very tuned into the ever evolving tactics and practices of marketing and the digital landscape, et cetera, et cetera, that you have to be. But if you want to be a great marketer, you go back to university and you study human behavior, you study history, you understand and learn about Greek mythology. Greeks got it right. They knew already at that time, 12 archetypes of human storytelling. (01:01:50): And Cole, you probably know already all about this kind of thing. And you can organize it all according to these 12 archetypes. And Hollywood is built on the understanding of these archetypes. And any great movies will have the rebel in it, and it will have the sage in it, and it'll have whatever that comes together and friction is created and all that kind of stuff. Learn that. Learn art, right? Learn philosophy, learn psychology, learn all of those arts, because that is a foundation for you to be a great marketer that will give you a platform to understand, analyze how people are thinking all what we do, right?", "token_estimate": 580, "speakers": ["Niclas Bornling"], "start_timestamp": "00:59:25", "end_timestamp": "00:59:25", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "9d4a05c6-326a-4c48-b327-c627122a36df", "episode_id": "e877e597-927d-4488-b6fa-b458e39c6353", "cms_item_id": "68225dfc7bb476527f8c4930", "chunk_index": 22, "content": "Cole Heilborn (01:02:39): Yeah. Well, Niclas, thank you for the time. Thank you, Cole. Thank you. Thank you for the perspective. Thank you for the ideas, the insight, and also just, I know you put this disclaimer out there before we actually sat down and recorded, but this episode, these ideas are yours. This doesn't mean that everything we've discussed isn't true or is true. There's obviously nuance with everything. Yeah. I just want to thank you for coming on the show and sharing some of your ideas. If folks want to follow along with you, if they want to connect, talk more. Where can people find\n\nNiclas Bornling (01:03:18): You? They can find me on LinkedIn as usual, right? I'm there and I'm more than happy, honestly. I would love even more context from people that just kind of ping me and ask me from experience and guidance and mentorship or obviously projects where I can be of help for a company or the brand.\n\nCole Heilborn (01:03:46): Amazing. Any last thoughts before we sign off?\n\nNiclas Bornling (01:03:51): No, I think we've touched on quite a lot of different things. There is more to talk about obviously, but we'll do that another time.\n\nCole Heilborn (01:04:00): Yeah, it sounds like we're going to get another episode on the books. We're going to talk about the lessons that we can learn about branding from politics, so stay tuned. We'll see if we can bring to you listeners here. That'll be an interesting conversation. So stay tuned. Alright, Niclas, I hope you have a great rest of your day. And yeah, we'll check in and see how any of your predictions or theories pan out over the next couple of years here. It'll be interesting to see for\n\nNiclas Bornling (01:04:26): Sure. They're probably going to be totally rolling.\n\nCole Heilborn (01:04:30): Well, we'll listen and we will evolve and adapt as we go. Alright, thanks. Hope you have you a great rest of your day. Bye bye.\n\nCole Heilborn (01:04:39): Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple. ‍ ‍", "token_estimate": 520, "speakers": ["Cole Heilborn", "Niclas Bornling"], "start_timestamp": "01:02:39", "end_timestamp": "01:04:39", "podcast_index": 174, "episode_name": "EP: 174  Tectonic Forces are Changing the Industry - Will We Listen?", "slug": "ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "web_url": "https://www.portsidepro.com/podcast-feed/ep-174-tectonic-forces-are-changing-the-industry---will-we-listen", "guest_name": "Niclas Bornling", "guest_title": "CMO | Former Brand Strategist at Salomon and Black Diamond", "categories": ["brand", "industry-trends"], "short_description": "In this episode, Cole sits down with Niclas Bornling, an outdoor industry veteran, to discuss the challenges faced by outdoor brands. They explore the lessons to be learned from the decline of brands like Quicksilver and DC Shoes in the early 2000s and how those lessons can be applied to the current state of the industry.", "podcast_length": "1:04:51"}, {"id": "cbbdb5f4-4cf7-42dc-8b9d-a6766ef712f7", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 0, "content": "Fitz Cahall (00:00): I think AI has kind of sat down on the toilet finally and is starting to take a shit on the internet to be super blunt about it. It is happening, and it's not necessarily that it's like, oh, it's creating things that are so magical that everyone's doing things. But no, if you look at it, you look at tools like Perplexity or if you look at tools like Chat GPT, they're starting to draw traffic away. I mean, even Google itself, it's creating the AI assisted search, right? What the heck? That's a crazy thing is that it's actually leading to the demise of its most potent revenue stream. It's a tricky moment where I think it's less clear of what do I do or how do I spend my money? Or where do I put my energy? ‍\n\nCole Heilborn (00:39): Welcome to the Backcountry Marketing Podcast. I'm your host Cole Heilborn. On this podcast, you'll hear from leaders in the outdoor marketing industry discuss the gritty details of their work, as well as the latest challenges and lessons they're learning along the way. If you want to hone your craft and become a stronger marketer, then this podcast is for you. This podcast is produced by Portside Productions, an outdoor film production company based in the Pacific Northwest. If you work at a brand or agency in the outdoor industry that needs help bringing a video project to life, head over to portside pro.com and send us an email we'd love to help. ‍\n\nCole Heilborn (01:11): Welcome to the Backcountry Marketing podcast from Portside Productions. Today I'm sitting down with Fitz Cahall. You've probably recognized Fitz's name. He's been in the industry for a long time. He's the Creative Director at Duct Tape Then Beer. He's the voice behind the Dirt Bag Diaries, and more recently, the Climbing Gold Podcast with Alex Honnold. Fitz, welcome to the show. ‍\n\nFitz Cahall (01:29): Thanks for having me, Cole. Appreciate it. ‍", "token_estimate": 474, "speakers": ["Fitz Cahall", "Cole Heilborn"], "start_timestamp": "00:00", "end_timestamp": "01:29", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "c5ea7cc4-3504-4eb6-bee5-2bf0931de1c5", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 1, "content": "Cole Heilborn (01:32): You've been on a name on the list that we've been wanting to bring to the show for a while now, and I think it's serendipitous. It's here, we're doing it. I feel like I've listened. I think most people have listened to. How many millions of people do you think have listened to your voice over the years? ‍\n\nFitz Cahall (01:46): Oh, I don't think it's millions. I think, I don't know. That's really hard to say because audience comes and goes through time, but quite a few people. Maybe it's the millions, I don't know. Yeah, not sure. It's hard to say that exactly, but yeah. ‍\n\nCole Heilborn (02:04): Well, I'm excited to bring you onto the show and I'm really excited to jump into our conversation. When we connected earlier, you mentioned we've been kind of going on a theme here with the podcast. We've been talking about just all of the changes and some of the turmoil and just some of the upheaval that's happening across not only the outdoor industry, but also the marketing in our conversation, what we're talking about today as the media world. And I think you said there's a lot of, you said there's a galactic upheaval in the marketing and media world right now, and I think that sentence that triggered me and I was like, oh, okay. We need to bring Fitz on and hear what he has to say. And I think no better person to talk to than someone. How long have you been in the media world? How long have you been doing this? ‍", "token_estimate": 364, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "01:32", "end_timestamp": "02:04", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "64562a1b-aa1d-4b17-8536-a4feeb1befe7", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 2, "content": "Fitz Cahall (02:47): It's been my entire career, essentially. Yeah, for the most part. I mean, from a standpoint of, I would say this is the third time there's been a really big shift, or we're the middle of shift, and the first one happened right when I came out of school in 2001, and that was sort of the first dotcom bust, and that was a crazy moment where there were all these new, especially I was in Seattle, so there was people leaving school to go take a job in marketing. They'd be in the communications department and go out there, and I was getting our job offers to leave school basically at that stage. And then it all just fell apart and I wanted to work in journalism, and all of a sudden I found myself competing with people that had 10 years of experience for entry level jobs because there was a deep level of, it was the first big downturn in print journalism. ‍ (03:45): And then, yeah, I went through it again in the 2007, 2008 era where with the Great recession, but there was also just this giant shift of the internet was coming at that stage. I mean, obviously it had already been there and it was happening, but this was the moment where I think people's consumption really switched. And I was a great beneficiary of that moment of change and upheaval where I just was like, I'm psyched on this. For me, I was working for magazines and in kind of print, and I was like, I didn't quite make it in that world. I was right on that cusp, and if it had continued the way it was, I would've ended up more of in the print space. But I unfortunately, fortunately, got cut out and just was able to kind follow through on some of the ideas I had about what would happen online, and that's what I did. Yeah. ‍\n\nCole Heilborn (04:42): And you think we're in this third upheaval now for, can you kind of give us an opening statement? You used the word galactic upheaval. ‍\n\nFitz Cahall (04:48): Oh ‍\n\nCole Heilborn (04:48): Yeah. Why do you think justify that for ‍", "token_estimate": 495, "speakers": ["Fitz Cahall", "Cole Heilborn"], "start_timestamp": "02:47", "end_timestamp": "04:48", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "702acc63-544e-48f0-86a0-47ce964cf16b", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 3, "content": "Fitz Cahall (04:51): Me? Oh, yeah, justify. Well, I mean, I think it's good to step back and think about our own habits. Sometimes when we think about big, big trends, it's like, what's happening with you? How are you participating? How are you showing up? Are you using the internet? It's a television, or are you using the internet? It's a library. And those shifts happen over time right now, and I think what's going on right now is that one, as much as people want to say it, there's definitely an economic downturn in marketing or in media in those two spaces. Big agencies like Wyden and Kennedy are laying people off. This is happening across many different industries, but it's impacting media and marketing significantly, I would say right now. And that's always going to happen. There's always going to be downturns, but there's something about this one where it just feels a little less clear about how it's going to come out of it and what it's going to be. ‍ (05:53): And there's obviously people that will preach the evangelism of ai, but the reality is that more and more audiences have become fractured. Where this is happening is on a deep, deep level, they've talked about this for a lot of years, but I think right now what we're seeing is everyone has this very nuanced interest and then it's being catered to them by algorithms. And we go from there. And I mean, that's why I think if you think about it, what's the last time there was something like a Game of Thrones. There's a lot of great TV out there right now. There's a lot of really cool series, but when's the last time that there was a Stranger Things moment where half the country tuned into something like that? And that hasn't happened in a while. And if you take a step back and you think about that, the same is true for what's happening on social media too. ‍ (06:48): And so this is impacting kind of every different level is that on one level, whether you are an influencer, whether you are kind of a mid-level media outlet that caters to stuff online or whether you're a big rever is trying to compete against Netflix, this is a super difficult moment in time because audiences are spread out. It's hard to create something that captures so many people's attention. And then on top of it, it's like, I think AI has kind of sat down on the toilet finally, and it's starting to take a shit on the internet to be super blunt about it. It is happening. And it's not necessarily that it's like, oh, it's creating things that are so magical that everyone's doing things. But no, if you look at it at tools like Perplexity or if you look at tools like Chat, GBT, they're starting to draw traffic away. ‍ (07:41): I mean, even Google itself, it's creating the AI assisted search, and that actually is hurting its own advertising business. And so what the heck, that's a crazy thing is that it's actually leading to the demise of its most potent revenue stream right there because it's drawing traffic away from people that were hosting ads that were fed, fed to a bite by Google. And that's kind of crazy. So if you look at that, there's this big level of upheaval on a lot of different sides, and it's harder for creatives to know what to do, and it's harder for people that want to connect to audiences and customers. So it is, it's a tricky moment where I think it's less clear of what do I do or how do I spend my money? Or where do I put my energy? I think it's a trickier moment in time than I've personally seen actually out of the three moments of big transitions ‍", "token_estimate": 889, "speakers": ["Fitz Cahall"], "start_timestamp": "04:51", "end_timestamp": "04:51", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "668a4464-5cb0-4655-897d-f571a6353630", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 4, "content": "Cole Heilborn (08:46): And in those three transitions outside of ai, is the main change that you've seen through that, just the hyper silo compartmentalization of people, the fractured audiences, is that one of the bigger changes that you've seen? ‍\n\nFitz Cahall (09:01): Well, there's a couple of things that's happened. Some of the, I mean, one, there was the way that systems work, it's the other day NPR was reporting that the Washington Post has lost 50% of its traffic since 2020, which is kind of mind boggling. That's a crazy thing. And even if you look at something, there's reports about some of the sort of more right winging outlets like Breitbart News and the Washington Post, Breitbart, they really relied on Facebook. They relied on that algorithm of people sharing and getting angry with each other. And then basically that algorithm's changed. People are also like, I can't handle this more. We're becoming savvier maybe as humans, hopefully that maybe we realize we really shouldn't be battling with each other all the time online. And what that's ended up with is this giant loss of audience for these people, for these outlets. ‍ (10:04): And obviously there's been some big name, you think about vice, you think about all these different things. There's been some big companies that have gone under, and part of it's probably a statement on how those business models were created. They were sort of free where it was like, this is free. It's supposed to go viral. Realistically, some articles provided most of the web traffic for them, and then there was just other stuff to keep regular subscribers or regular people paying attention, but they were aiming for that sort of viral moment. And some of that's sort of gone away on a lot of levels. ‍ (10:44): Then I think on the other side, there's a side of it where it's like we're kind of getting used to TikTok where someone will make a video, gets 25 million views in two days. You're like, wow, that's incredible. But then if you're a creator that drops off a cliff, good creators are kind of able to replicate it, but they don't do that every day. And how is that sustainable, that model, if you're a creative and you're like, okay, I am putting all my money on black, spinning the wheel and seeing what comes up, that's not good for creatives, that's not good for people that want to support creatives. Frankly, it's not that awesome for people that want to build community. So does that answer the question? ‍", "token_estimate": 622, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "08:46", "end_timestamp": "09:01", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "a2a90749-407b-466b-807a-8cbaf25c2a0f", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 5, "content": "Cole Heilborn (11:26): Well, yeah, it sounds like people are just confused. Is that a fair statement creators brand side? You and I are like, is everyone just the chips are up in the air and we're just waiting for them to fall, and in the meantime we're all just trying to pick our way through the mess? ‍\n\nFitz Cahall (11:42): I don't know. I mean, I think there's, some people look at this and because anytime there's sort of confusion and chaos, there's opportunity. So I think there's some people that are charting courses that are like, okay, what am I doing and what am I trying to do? And I think for me, that's been, to me, I've been, the answer doesn't, it's weird. It's both on a business and on an emotional level. And it's funny to think of those two things actually like aligning. But what I'm banking on the way I'm going is that I don't believe more is more. I don't think that that's the solution. I don't think that just it's to do that. It's not sustainable. It's not on a personal level, it's not sustainable for teams. It's not really sustainable from a budget standpoint. And it's like you might game the system for a little bit, you might be able to do that, but ultimately it's a pretty hollow endeavor when you're always just thinking about more. And I think for me, what I'm trying to think about is deeper is I'm trying to figure out ways to do that where I'm like, Hey, I might be willing to give up some audience to have a deeper and arguably better connection with more people. Does that make sense? I'll give up volume for quality. And ‍ (13:10): That's what I think for me, that's what I've sort of charted with the things we're doing is I'm like, that's okay. It's okay if this doesn't reach a million people. It's okay if it doesn't even reach a hundred thousand people because I think some of that is just BS anyway, right? It's glancing and what I'm trying to do are things that obviously I would like numbers, I'd more reach and more deeper connections. But I think the way through that is through quality, through thoughtfulness, through caring, through empathy and curiosity. And I know that sounds sort of woowoo for talking about business, but that's the path I'm charting right now. And I think that I see other people trying really cool things and going for it. It's not a bad time to do that, but it doesn't feel as clear to me as other chapters have. ‍", "token_estimate": 599, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "11:26", "end_timestamp": "11:42", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "a56e77c2-1e57-4590-b379-ab7d2a9dedd6", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 6, "content": "Cole Heilborn (14:10): Why do you think that is? ‍\n\nFitz Cahall (14:11): I think that the side of it is that the amount of volume, the amount of noise, and I makes it hard to break through sometimes, frankly. I mean, that was a gift of when I started doing what I was doing is that there wasn't that much out there. It was like the dirt bag dairies when I started. It was probably in the first thousand podcasts. And there are millions and millions of podcasts now. And it's not to say that you can't break through with a cool podcast. Now that's possible, but the path to that is very different. It's way more sophisticated and frankly put, it takes more money than it used to. Yeah. And then I think that's an interesting thing is that because things take more money, that often maybe means there's an investor behind it or there's some level of that and then all of a sudden what that does or how that allows you to create or how that allows you to, the sort of timeframe you have to build something is different. And I'm not saying that's a bad way to go, but that's just a reality on that whole front. ‍\n\nCole Heilborn (15:24): So I'm going to try to connect a couple dots here and lemme know if this makes sense. I'm curious to hear your thoughts. So there's obviously been a massive increase in the amount of content and stuff out there in the internet to consume. It seems like there's a correlation between the amount of volume that there is and the silo of channels, the silo of people. There's millions of podcasts now, and if you want to stand out, you now have to create a show that's theoretically super niche, very targeted to a specific audience to kind of take a slice out of that total volume. And I'm wondering, is it a chicken or the egg situation? Are we creating more and more content to stand out by choosing a very niche audience like this podcast? And is that contributing to the overall problem? Maybe it's not a problem, but the overall phenomenon of mass audiences turning into niche audiences, ‍", "token_estimate": 506, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "14:10", "end_timestamp": "15:24", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "5cf6c4f7-0711-4533-8d31-2453aeb85dea", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 7, "content": "Fitz Cahall (16:15): Right. That's a really good question. I mean, sometimes I look at things and I'm like, that is so niche. I'm like, I couldn't handle that. I couldn't handle being the creator of that. And obviously I do something that's fairly niche in terms of I make stuff for people that are rooted in the outdoors that are trying to have connections to that, that are trying to have connections to this wonderful community that is out there. And that to me feels broad enough. And if anything, it's funny because my instinct of the things that I might be creating in the future, I would be looking for broader. I would be looking for connections between bigger groups where it's like we're thinking about this more thematically about what binds us as humans or what are the sort of what's analogous between these different niches and try to build that way. ‍ (17:15): Frankly, if I were to go back and be launch a new show, I'd be thinking about those. I'd be thinking about how I can have a broader set of interests and diversity out there, but having it rooted in a really core principle that many people share across many different places in our society and culture. So I know, does it answer your question about which came first, the chicken or the egg and Yeah, you're right. I mean the niche is a really good thing. And I think that there's this great book I think called Learning How to Ask by Amanda Palmer, who was this singer musician in a group called The Dresden Dolls, which was kind of goth folk punk kind of weird thing. She wrote a great book and it's for all creatives, and it's basically just this idea of asking and in it, I remember she had this line where it's like, to make a living doing this, you only need a thousand people. ‍ (18:28): And that I was like, really? That's an interesting thing. At some point when I came across this book and then I thought about it and I thought about how sometimes the casinos out in the middle of nowhere, they'll be like, I don't know, sticks is playing or something that's from a different era that didn't have its hall of notes moment or even journey or something like that. It's something that's leftover, but there's enough people out there that still can support this band and people can still make a living even though they're nowhere near charting and they're not doing anything like that and it's because they have their small powerful thing. So I think that that's a good example. I know it's like we don't want to be an aging sort of rock band from the 1980s probably, but that's acceptable too. ‍ (19:26): Yeah. So I guess I worry less about that. I don't see that such as an issue of being like, oh, I care a lot about something. I want to talk about it. It's just the reality is that there's going to be fewer number of people that do that, and people will care insanely about, they care so much about such tiny details out there at certain points in their life, and that's up to them. The bigger thing is, I think the more important thing that people should think about is how they're consuming. Because I think a lot of people would say, Hey, big say, let's take local news. Let's take the Seattle Times or even The Washington Post, something like that. It's probably good that that exists. It's good that there's journalists out there that are doing this work and doing really good reporting. One of the things I subscribe to is the Atlantic magazine. ‍ (20:23): I really appreciate it. It's super in-depth reporting. It's sort of the sort of antithesis of what people say is people's attention span there. And it's like they give me me things that are going to take me half an hour to read or an hour to read maybe even. And that's something I support. And so as a consumer, and I would also say to the people that are investing in advocacy, you have to support the things you think should be there because they will go away if you don't, and you can go spend money or spend your time on a meta product or on a TikTok product. And I'm not throwing shade on that. There's great things on there, but if you're just sort of doing this and you're just waiting for the next dumb ass dopamine hit to get you, that's jacked. ‍ (21:12): And if you're supporting that, that's messed up because that's what we're going to end up with. We're going to end up with a phone that's a modern version of the cigarette that we're all sitting there twiddling or holding in our hands. And to sort of sit there and say that is that we do, I think as people that support creative endeavors, that support community, and then also as consumers of creative endeavors and community, we have to get behind the things that we think should be there. And that means actually giving your eyeballs to it or supporting a Patreon or doing a substack or just being like, I'm not going to rip off someone else's password on this. I'm actually going to use it. And there's that level on the consumer side and then to the brand on the brand or the marketing side is like, you do not want there to be just meta and TikTok in this world that will not be good for you, that will not be good things for you as those monopolies tighten it. It's like that's just not a good thing. So just think about how you're spending your money, how you're using, how you're engaging, who you're supporting and how you're building community, I think is a vital question if you're on the brand side right now to ask. ‍", "token_estimate": 1362, "speakers": ["Fitz Cahall"], "start_timestamp": "16:15", "end_timestamp": "16:15", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "2ab18510-4a32-4a57-b07b-1ea6ecc6574f", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 8, "content": "Cole Heilborn (22:36): I so I love your vision. It sounds optimistic, but I just, ‍\n\nFitz Cahall (22:40): It's sort of optimistic. Sorry, should I dial it down? I am trying to make sure I don't seem too doom and gloom. I'm a little bit optimistic, but I'm also pretty damn pessimistic too. ‍\n\nCole Heilborn (22:52): Well, and I think I kind of am too. And I wonder, has the population at large, have we not been trapped by the metas and haven't we been programmed enough by the dopamine hits in our brain that just keeps scrolling? Can we really break out of it? And I wonder too, you're someone that creates media, so therefore you think about this stuff. Does the average person think about the content that they're consuming, where they're getting it and doing so how, who they're supporting? ‍", "token_estimate": 200, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "22:36", "end_timestamp": "22:52", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "e31ae937-dbbb-423d-91cf-f44a3e603eb8", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 9, "content": "Fitz Cahall (23:24): Yeah, well think about it. That's a great question. Some people do, some people don't. But what I think what would be better is if more people did, and I'm going to use another example. We were talking about like, oh, how do you support the things right now in Seattle, there's a lot of our city's a lot. It's changed a lot. It's gone through a pandemic. And for some of the food places, it's been interesting. There's been some sort of classic big fan favorites that are just closing. You are kind of like, really? That's closing? That's an institution. And it's just because people sort of forgot. And then you think about, well, when was the last time I was there? And you're like, the last time was there was six years ago or five years ago because my habits changed and I'm doing something different, et cetera, et cetera. And you're like, well, I didn't go to that place even though I thought I was cool. And that's an interesting thing is like, well, there's a level of it of if you think something's cool, you should probably go there. Or if you think someone's doing a cool thing, you should probably support that. And that said, so we're talking about that. That's sort of analogy of that's happening with media outlets. ‍ (24:44): It's funny, if you think about, I'm reading another Michael Pollan book, but there's the Omnivores Dilemma, which is a very famous book about the nature of food. And it was written probably 20 years ago, I think it was. And that book was super impactful for a lot of people where they started to think way more about what they were eating, what they were putting in their bodies. They were like, should I be eating the impact to me? What's the impact to the planet? Or do I need to be an all vegetarian side? What's the impact? There was this great sort of discourse on different types of ways that people can eat and those impacts that they have on farmers and planet and all that stuff and on us, right, on health. And that was something that I think a, some people thought about 15, 20 years later, way more people think about that now than they did 20 years ago. ‍ (25:49): I mean, on a crazy level in terms of how we think about organic food, all that, that's almost sort of just, we don't even think about it half the time anymore. And so what I'd say is it's possible to think about the same way of what we're consuming mentally, emotionally, what's like a built, built in just sort of the equivalent of the McDonald's french fry where our pleasure centers light up and you're like, but that's not good in the long run. A little bit's fine, but not good in the long run. What's the equivalent of that online or our deeper things better for us? Things that take more time, that make us think that build empathy, is that better? And so I think that there is a moment where a lot of us could take a second and really reexamine the relationship we have with how we consume, and one those on ourselves, on our emotional being, the impacts of that on our community. ‍ (26:51): And even on a crazy level, the impacts of that on the environment. It's wild. I don't know, you're in Washington state too, but I don't know if you caught this, but I, we've been having a lot of push and I think this year was the year that I thought that everyone thought that maybe we would get to all renewables and they had to sort of reexamine that and be like, we can't do it. And a large part of that was because of the data centers that are powering AI things and that request that has grown by 20%. So there's just this new strain on the grid that's actually happening how we all are freaking using our phones. That's wild. That's a wild thing. And so I think that there is a moment where we can take a step back and think about it of being like, cool, if we approach this the same way we think about how we eat or how we take care of our health, would we be doing a better job of being consumers, being a community supporting things? And I don't know, maybe there's room for optimism in that. And I think that depends on what you think of people. I think that sort of depends on whether you're optimistic about people or not. ‍", "token_estimate": 1045, "speakers": ["Fitz Cahall"], "start_timestamp": "23:24", "end_timestamp": "23:24", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "c7f3fc89-c7b9-47ef-b910-ca9569541dc8", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 10, "content": "Cole Heilborn (28:10): Do you think that we're evaluating our consumption as a whole? Are we becoming more conscious of our individual consumption of everything, of food, of energy, of media? Is that a trend ‍\n\nFitz Cahall (28:24): That ‍\n\nCole Heilborn (28:25): We're seeing? Is that a habit that we're seeing or I'm not reaching too far. ‍\n\nFitz Cahall (28:28): I feel like you're reaching too far. I'll be blunt. I mean, I think that it's so hard. I feel like I sound like someone who works in self-help or something like that right now. But on a level, I think that's maybe a bit much. I think if I had to take a step back, but I do think everyone's journey is different. Everyone's level of awareness and ability to see how they fit into a world and into a community is different. I think it's always a better thing when you ask those questions of yourself in any regard of what role am I playing here versus just worrying about what meeting you have tomorrow. And you can't do that all the time, that's ridiculous. We'd get nothing done. We'd have a tough time supporting our families, but it's worth taking a moment and thinking about what choices am I making and how do these choices ladder out into the world and into my own happiness? ‍ (29:28): And whether you're doing that with food or whether you're doing that with your media consumption, whether you're doing with that, when you're thinking about how you're doing your ad spend, it's like a worthy thing to go through, even if you make the opposite choice and you are like, well, I can't make that choice right now, but ideally I would be making some other choice. That's a worthy process to go through to think about what impact does this have, what goes away? What benefits, who benefits, who loses, who maybe gets left out in the cold? And I think that that's a great question to ask, especially when you're trying to grow something, which I think we're all trying to, I think, grow connections to the natural world, to each other, to the outdoor community, to things that cause to create joy in life. I think that anyone on your podcast would say, yeah, that's actually probably what I'm in the business of doing. So I think we think about that. We think about that in, we've done a way better job thinking about that in the last 10 years about how we're inviting people that don't look like the two of us into our community. How do we support those projects? How do we do that? And we've done a better job. That work needs to keep going, obviously. But that's a great example where somebody sat down and thought, who's being left out of this? How do I change that? What do I do? ‍ (30:53): And that's a byproduct of that. It's also a byproduct of people raising their hands and being like, Hey, you should support this, right, too. It's like same dynamic. So I don't mean to say it's all there, but it is a byproduct of people sitting down and having real conversations about When I spend my money this way, or when I use my time this way, what gets supported and what doesn't and does that align with my values? And hopefully they do ‍", "token_estimate": 777, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "28:10", "end_timestamp": "28:28", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "c9b44b4a-f42e-4b73-897d-59197197bebe", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 11, "content": "Cole Heilborn (31:22): From the, I'm flipping the script a little bit here. ‍\n\nFitz Cahall (31:25): Go for it. ‍\n\nCole Heilborn (31:26): Changing gears, whatever metaphor we want to use from the brand side. There's so many options out there. There's so many ways to spend money, there's so many ways to engage, to connect, whatever. I mean, do you envy, do you wish you were in-house at a brand somewhere? Do you wish you were a marketer somewhere with all of these options? Or do you enjoy the seat you're in these days? ‍", "token_estimate": 131, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "31:22", "end_timestamp": "31:26", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "be34a726-8aa8-4cb6-b56c-2eb20711d0ae", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 12, "content": "Fitz Cahall (31:48): Oh, that's, well, that's a really personal question and a really good one. What I do right now feels difficult. It's felt difficult even when it's been going really well. I like difficult things. This has been the journey that I've taken has I got to do. It's like my partner and my life partner is my co-owner of my business. I've got incredible crew, so it would be hard for me to ever think that differently. And oddly enough too, the way that it's all the way cookie crumbled. I mean, aside from odd jobs and being a climbing guide and doing kind of manual labor and stuff like that, I've never had a boss technically, which is kind of wild to think about. I mean, a few journalism jobs at the beginning I did, but so it's sort hard for me to imagine that. And while I learned a lot about that and I know what people go through internally, I'm not sure that's where I was. ‍ (32:48): I think if I were, there's a company that I work with called the Bull Ring Project, which has climbing gyms, climbing gyms across country. And that's a really cool thing is that I like that sort of side of it. That's a cool opportunity. Their goal is to grow the sport, right? It's cool. It's there. They're not going to, that goal is their buildings are only so big. You can only, there's fire codes, right? It's not like the TikTok model doesn't apply to the bouldering project on a level, and it's more analog in that way. And you have to think about that. They have to make this product that's great, and it has to be great from a design level of how they build the buildings to how they create the Boulder problems, to how they engage with their community. And it's crazy if they do all these sort of very, we would call it the Amish way here, we make a joke about that. It's very old school in terms of being like there's things it just takes, it's less performance marketing and more deep connection and thoughtful design. And so projects that might be appealing to me where I would be interested in something like that where it's like my goal is not to sell 3 million widgets. I don't mean to crap on Stanley and the Stanley town, but that to me is just, I just have no interest in that and I don't know how to say it other than that, ‍ (34:41): I have no interest in that. So I think it's like, it's fine if you do. I don't mean to crap on anyone, and it's jobs to sell jackets, and there's nothing wrong with that. And I support that. And I've been there, and I've actually really appreciated the education I've gotten and working with brands through the years and some of the brand work I've done in terms of what goes into making a jacket and how do you do it, how do you do it better? I love that process. But to me, I'm less interested. I have empathy for people right now that are working there because they're probably working with reduced budgets right now a little bit. And they're like, oh God, how do I do this? What's the right tactic? I've got to support product right now, and I've sort of got to take care of the community. ‍ (35:26): I've got to follow through on some of the DEI stuff I've done. That's a tricky situation to be in. And I think what I'd say is just try go through that process of being like, well, here's what it is. This is what I got. This is how I think I should spend it. I've got to spend it in a way that makes sure that my company keeps going, that I'm successful on the role that marketing ultimately does, but how's it aligning with my values and who's winning and who's losing here? And is there a way to potentially do it better so that the people that I would prefer to see succeed are succeeding versus something like meta? And that's a fair process to go through, and that's like, that's an important thing to do. So I guess I don't envy that. That's a tough call to make. I don't have to do that right now, but there's a way to do it. And I would just say be thoughtful about it. ‍", "token_estimate": 987, "speakers": ["Fitz Cahall"], "start_timestamp": "31:48", "end_timestamp": "31:48", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "4245e92e-8254-413a-915e-9cdae5d6c72f", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 13, "content": "Cole Heilborn (36:34): Over the weekend, I was in Telluride at the Mountain Film Festival and it brought up so many thoughts and ideas, especially on the drive home. I had a lot of hours to think, and I had this idea, I had this question, and I want to run it by you. If you could wave a magic wand and change anything about the dynamics of marketing or the dynamics of how a marketing department works, who it reports to, who it's beholden to, if you could change anything about this department, what would you want to change or what value system would you want to change? Or it doesn't have to be, it could be high level, it could be floor level. ‍\n\nFitz Cahall (37:18): That's a really thoughtful question. Sorry for taking you, it. Take me a second to do this. I just want to come up with a thought because it's a thoughtful question. I want to come up with a thoughtful answer, and I just hadn't, I've never thought of that. I've never even really thought of that as an something that's actionable. ‍\n\nCole Heilborn (37:34): It might not be an option. ‍", "token_estimate": 265, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "36:34", "end_timestamp": "37:34", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "0c1e12fa-f6e3-4010-8b1d-76da945327b0", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 14, "content": "Fitz Cahall (37:36): Yeah, no, I think it's interesting because you're like, well, I might start with capitalism. There's that side. I go to the high level, but I think I would be like, let's bring it down a notch. And to think about that. And I think that one thing I think would be good for brand teams and for marketing teams to do is to take, for me, I studied journalism because I was like, oh, if I do this, I get to learn something new every single day of my life. If I take this lens and I'm doing it, I thought I'd be covering politics. That's where my start was, was like, I'm interested in this. I want to learn about it. I remember one of my first jobs was covering state politics down in Olympia, and I realized, oh, it's about the money. And I got all excited it as a 3-year-old learning about the state budget, I was like, nerd, right? ‍ (38:39): Full nerd. But I was learning about something. It's like, I think what I would say is if I had to wave a magic wand and do that is that maybe some of the marketing departments, while they relied on tools and proven tactics, I would always make a place for curiosity in it. And I would always make a place for learning and not just about more performance marketing tools or better SEO, I would be curious about the world, the people that inhabit the community you rely on and support. And I would be just, I would just be curious. And that's how I think if I were to say, if I were in charge, if I were a brand leader on a level, I'd be like, let's figure out how to integrate some of that into what we do, because I think that that leads to great places. ‍ (39:41): And I think that making room to have conversations without people outside of your organization with different perspectives, taking that time versus just, it's just a huge thing. And it's not easy. It's hard. I have to work on that all the time of being like, oh, I'm seeking out different perspectives and different opinions on things. It's not small, but I think that that's led to, whether it's through reading or whether it's through meeting new people or going to things that are sort of way outside my normal realm of groups I'd be in and expose to different ideas. It's rewarding. So I think if that's the magic wand tool, I would be like, and it's actionable. That's actually an actionable thing that people can do versus, wow, I wish we didn't have to sell jackets. That's never going to happen. That's the function of marketing. What does it go? The tail can't wag the dog. So that's the reality. So that said is like, what would be better? It would be better if more people were curious, because I think that that ultimately will lead to better outcomes for the company you work for. And it's a way where you can be quite human, quite engaged, and we're not worried about the dog or the tail wagging at that stage because maybe it allows us to find better purpose and better meaning in our work we do too. So yeah. Interesting. ‍", "token_estimate": 742, "speakers": ["Fitz Cahall"], "start_timestamp": "37:36", "end_timestamp": "37:36", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "0535baee-0ba7-48ff-9fd9-7e9d7c19796f", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 15, "content": "Cole Heilborn (41:18): Something I think about a lot. ‍\n\nFitz Cahall (41:19): What would you do? What would you do? ‍\n\nCole Heilborn (41:22): I don't know. I feel like my thoughts, I haven't fully figured out what I'm thinking, if that makes sense. If that makes any sense. Yeah, it does. I went to Mountain Film with the intention of this podcast hasn't come out yet, but I went there and I wanted to interview some amazing filmmakers and some amazing folks from the brand side to just talk about, I love storytelling and I love getting to tell stories. And I'm always just so curious about the role that storytelling has in marketing and where it fits and the value. And I think everyone on this show, every marketer talks about the value of storytelling. I think that's a default. But then when it actually comes down to making something and telling a story and then deploying it and amplifying it into this world, it's complicated and it's messy. And the ROI is elusive, and there's so many questions about something that seems to be such an ingrained truth. ‍", "token_estimate": 266, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "41:18", "end_timestamp": "41:22", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "6e79fd03-4cd9-40b4-a6af-0a57385c93a9", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 16, "content": "Fitz Cahall (42:24): I'll counter that and I'll be like, is the ROI elusive? If you were to take one step back and let's take, instead of being like, okay, here's my marketing campaign, and then turn, let's be curious. Let's take one step back or maybe 10 and let's zoom out. Let's think about the brands that are the best at stories. Nike, right? Yeah, Patagonia, how's that going? But I think, what else? Apple? ‍ (42:58): No, you zoom out preaching and you're like, what's the OI of having a story? What's the ROI of having an understanding your brand story, and what's the ROI of having ability to attract talent through a story? And you're like, when you take that step backwards and you zoom out on that level versus your fricking goddamn meta campaign you're running right now, you see a really different picture. You see a really different picture. And I think that the coolest thing is when somebody actually, the light bulb goes on and it's just like, oh, it's not just that I can support these cool stories that are in my universe, it's that I can become a story that the brand can actually take action. It can do things. It can act like a human. And when you give that brand, that agency, which is a tricky thing to do, it becomes powerful. And so on that level, yes, are, I mean, there's other brands that take different tactics that are obviously incredible companies where they're much more tactical. They're the science people, or they take a sort of war approach where we're like, we're going to dominate the other companies. They do it that way, right? ‍ (44:18): That's an approach too. But I think mean, I've heard it said it's like that there's science and there's the battle approach and then their story and that those are the three major ways you build a brand. And most people, when they think of brand, they're thinking of the story driven side of the whole thing. And yeah, I don't know, because I hear that same thing. You just thing be like, well, what's the ROI on that? And you're like, well, maybe the better question is how am I supporting it? If I'm working on this big story, am I bringing all the right tools? Have I saved the right amount of money to support it with events? Have I done all this is like story's proven? I think at this stage we can all say that story's proven. And if you don't, I don't think you're a history. I don't think you're actually a student of what's happening in branding in the last a hundred ‍", "token_estimate": 615, "speakers": ["Fitz Cahall"], "start_timestamp": "42:24", "end_timestamp": "42:24", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "174ed44a-b231-4fe5-90b2-bc1f48ac07e7", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 17, "content": "Cole Heilborn (45:13): Years. I don't disagree on the front lines. I feel like I hear those questions and I wanted to try to find an answer to that. ‍ (45:22): And so my thought was like, well, what prompted this question, this original question of what would you want to change about the marketing department? What I walked away from all those conversations with from the festival was like, maybe it's less about the power of storytelling and the value of it, and maybe it's more about maybe we need to change how we think about storytelling and how it integrates with marketing. Maybe it's a department level change. It's a change in the values of the business. It's a change in leadership, it's a change in the KPIs, the lack of KPIs that we're looking for. ‍\n\nFitz Cahall (45:59): I don't even know what kpi I means, I feel so embarrassed saying that I am just like, I forget. I can look it up. I've looked it up before, but I'm like, God damn dude. ‍\n\nCole Heilborn (46:08): It's like the one performance marketing phrase. I know. A key performance indicator. ‍\n\nFitz Cahall (46:12): Okay. ‍\n\nCole Heilborn (46:13): Yeah. I ‍\n\nFitz Cahall (46:15): Mean, I know some of 'em, but I don't know. ‍\n\nCole Heilborn (46:19): Yeah, ‍\n\nFitz Cahall (46:20): I know I sound like a dinosaur. I say that, ‍\n\nCole Heilborn (46:22): But I ‍\n\nFitz Cahall (46:23): Honestly don't care. ‍\n\nCole Heilborn (46:26): But I think that's what I walked away with was like, I wonder if, I don't know. That's what prompted the question. That's how I arrived there. ‍", "token_estimate": 386, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "45:13", "end_timestamp": "46:26", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "cb5997d3-5d12-456d-9495-e85fa918ae26", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 18, "content": "Fitz Cahall (46:34): Yes. Well, I think that's a worthy question to ask. And it, it's good. And I think that too, to the point of the disruptive moment, circling back to that beginning of this conversation where it's like one, it's disruptive. The outdoor industry's got a hangover. Let's just all be honest, it partied a little too hard, got a little crazy. Some of that was inflicted, self inflicted. Some of that was inflicted by crazy events, but that's happened. And then there's this giant sort of upheaval in media right now. And so when you circle back to that as being like, cool, it's a great moment. I mean, talk about opportunities of thinking about that, of when things are chaotic, it's an opportunity. So maybe there's less money to spend. So maybe it's thinking about, well, instead of just unloading that right now in a certain way, or maybe you have to unload it in a certain way right now, maybe it's the time to start thinking about what you're going to do five years from now when it's gotten a little bit more normal. ‍ (47:34): What are you going to tackle or three years or two years ago? And instead of just being like, what's happening in spring of next thing with this jacket line? Think about the bigger picture, the bigger stories that you need to tell. Maybe there's an opportunity to do that and to set yourself up for that next chapter where it's a little less chaotic, it's a little less clear. And yeah, right now you don't know whether that money is going to be going to, I don't know, do an awesome project with a YouTube creator, or you don't know whether that money is going to be sponsoring an awesome, doing incredible work. You just don't know where that money's going to be going. But if you think about where you want to, if you think about that brand story, you're going to be in such a better position a few years from now, then you would, if you just sort of were like, I'm just going from the next meta campaign or the next, how's this performing, blah, blah, blah, all that you have to do that, it's there. But if you can take and carve out a moment of your time to think about with intention, that bigger thing, that's how you win in moments of disruption in my mind. ‍", "token_estimate": 555, "speakers": ["Fitz Cahall"], "start_timestamp": "46:34", "end_timestamp": "46:34", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "da9f8fbb-b702-4737-94a9-0ea9198b9883", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 19, "content": "Cole Heilborn (48:52): Yeah. So I mean, is that the key? If you had to leave folks with kind of a takeaway, how to ride this storm out, is it take the time to think about where you want to be in two years from now and then start there? Is that what you'd recommend? Are there any other takeaways for folks who are caught in the middle of all of this mess and trying to figure out how to make it through? ‍\n\nFitz Cahall (49:15): Yeah, I think so. I mean, I think it's a lot of what we've talked about, and I really appreciate this conversation. I feel like it's actually sharpened my thinking a little bit right now, which is I appreciate, but I do, I mean, I think if I had to have some takeaways is start thinking about the future. It's like, yeah, obviously we're in a little bit of a tough call right here, but if you can't work with somebody now, how are you setting up the relationship? So they want to work with you two years from now so that you still have that or that you let them know is the way to respond to somebody you've worked with for a long time to just ghost them when they email you because you don't have money? Probably not. So I would say, take a moment to think about two years from now or five years from now, where do you want to be? ‍ (50:12): And if you haven't sort of thought about those values or you haven't thought about that bigger brand story, now is a really good time to do that because if you're doing that two years from now when there is money or you have more resources to work with, you're not going to spend it in the right way. You're not going to do that. It's like then you'll be doing the work then and then you're behind. So yeah, I think it is. It's just thinking about that, take a moment, be like, take a second to adjust, take a section to write that own story for yourself, and even maybe put it down on paper is like, cool, five years now, this is what I want this to look like. This is what I want to be supporting. This is my vision for it. And that gives you a way better roadmap, whether you're doing it on a tactical level of where would my marketing budget, what would my ideal marketing budget be and where's it going to go and how am I going to do it? ‍ (51:05): What am I support? How am I making sure that I'm supporting my internal side of my things? How am I supporting my community? How am I building the whole bigger thing? And those are the questions I would be asking myself, even if I can't do them right now. Because to take a moment when it'll be too busy tactically, if it turns back on, people are going to be like, oh, man. And that's when people make bad decisions with their money. That's when people maybe green light an awesome film, but then can't figure out how to support it. They fail. They're moving so damn quick. They forgot to write the marketing plan for that film to capitalize on the story that they've supported. So I think that that's a great moment of being able to do that is like, Hey, if there's a little more space, just imagine yourself five years from now and what would you want? And I think a plan, an understanding of who you are, who your brand is, what you value, and then I think it becomes a lot easier to move towards those values, those shared values that you have with your customers. ‍", "token_estimate": 824, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "48:52", "end_timestamp": "49:15", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "f803836d-1d83-4fa7-b100-3540e99f7c05", "episode_id": "4e655238-9454-433d-98f1-d618ec895e19", "cms_item_id": "68225dfc7bb476527f8c493b", "chunk_index": 20, "content": "Cole Heilborn (52:13): Well, if we wrap it up there fits, where can folks find you? Where can people go and support you and your various endeavors? ‍\n\nFitz Cahall (52:21): Well, I mean, we've got a couple of shows. We've got the Dirt Bag Diaries, we've got Climbing Gold, and those are in full Swing, and they're incredible. And then the work we do like Duct Tape and Beer, it's funny, this is some of the work we do is talking about these various things, brand narratives, values, how do you turn your company into an actual story? How do you take action? That's been some of my favorite projects. Some of the work I've done through the years is actually some of that work. So we're on Instagram, we're on the web, we're out there. Yeah, we're doing our thing. You can find us. ‍\n\nCole Heilborn (52:55): I always feel like if it's a redundant question to ask, but it feels wrong to not ask ‍\n\nFitz Cahall (52:59): It ‍\n\nCole Heilborn (53:00): Because I'm like, well, maybe someone only accepts snail mail. I don't know. ‍\n\nFitz Cahall (53:03): Dude, I did, hang on one second. I can't remember that I told you, but we wrote a book too this year, and so people actually may be able to find me in person, which is rare because I'm a little bit of a hermit. And we'll be doing some live events later this year and going through. And so I'll be out in the community supporting the book. And the book launch is 30 stories, like some of our favorite stories from the diaries over 17 years, and it's cool. So yeah, I'll kind of be around ‍\n\nCole Heilborn (53:34): Where can people find the event venues, the dates ‍\n\nFitz Cahall (53:37): That I don't know yet because we haven't crossed that river yet, but we will be doing some things in Seattle, and I imagine we'll be doing some things. I know we'll be doing an event out in Duluth and probably in Minneapolis out in October, and we may do some East Coast stuff in Denver and Seattle, but if you follow along on Instagram or on any of the socials, that's a really good way to keep up to date on that. So yeah. Awesome. Excited for that. ‍\n\nCole Heilborn (54:06): Cool. Well, Fitz, thank you again. Hope you have a great rest of your day and appreciate the conversation. ‍\n\nFitz Cahall (54:11): Yeah, absolutely. Thanks for having me, Cole. Bye. ‍\n\nCole Heilborn (54:14): Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple. ‍", "token_estimate": 615, "speakers": ["Cole Heilborn", "Fitz Cahall"], "start_timestamp": "52:13", "end_timestamp": "54:14", "podcast_index": 177, "episode_name": "EP: 177 The Galactic Upheaval in Media with Fitz Cahall", "slug": "ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "web_url": "https://www.portsidepro.com/podcast-feed/ep-177-the-galactic-upheaval-in-media-with-fitz-cahall", "guest_name": "Fitz Cahall", "guest_title": "Creative Director at Duct Tape Then Beer and Host of the Dirt Bag Diaries", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Fitz Cahall, the Creative Director at Duct Tape Then Beer and the host of The Dirt Bag Diaries, discuss the current upheaval in the marketing and media world, emphasizing the impact of fractured audiences, AI, and the shift towards niche content.", "podcast_length": "54:26"}, {"id": "2863135d-cae8-4b79-993d-703d4d4f7326", "episode_id": "a05d7e73-aab7-45ac-842a-06ddc2c9830e", "cms_item_id": "68225dfc7bb476527f8c493c", "chunk_index": 0, "content": "Drew Pautler (00:00): If you don't participate in culture, you run the risk of your brand being invisible or boring or both. And so shedding the fear of playing in mainstream spaces is what it's going to take for us to break through this insular, albeit vibrant community, but one that is more attractive for more participation. I'm not just talking about people doing it, I'm talking about people watching it and becoming fans, whether or not they do it themselves, that's ultimately where we'll see the greatest gains.\n\nCole Heilborn (00:37): Welcome to the Backcountry Marketing Podcast. I'm your host Cole Heilborn. On this podcast, you'll hear from leaders in the outdoor marketing industry discuss the gritty details of their work, as well as the latest challenges and lessons they're learning along the way. If you want to hone your craft and become a stronger marketer, then this podcast is for you. This podcast is produced by Portside Productions, an outdoor film production company based in the Pacific Northwest. If you work at a brand or agency in the outdoor industry that needs help bringing a video project to life, head over to portside pro.com and send us an email we'd love to help. Welcome to the Backcountry Marketing podcast from Portside Productions. Today I'm sitting down with Drew Pautler, founder and creative director of Good Fortune Collective. Drew, welcome to the show.\n\nDrew Pautler (01:20): Thanks so much for having me.\n\nCole Heilborn (01:21): Yeah, it's good to see you. I'm excited to have you on the show. I feel like I've been admiring your guys' work for many years now, and so when we have the opportunity to connect and start talking about what can our outdoor industry learn from the mainstream sports world, I was like, Ooh, this is going to be a fun conversation. So yeah, welcome,\n\nDrew Pautler (01:43): Very much looking forward to it. And yeah, feelings mutual. It's good to have a chat.", "token_estimate": 484, "speakers": ["Drew Pautler", "Cole Heilborn"], "start_timestamp": "00:00", "end_timestamp": "01:43", "podcast_index": 178, "episode_name": "EP: 178 Breaking Barriers: What Can the Outdoor Industry Learn from Mainstream Sports?", "slug": "ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "web_url": "https://www.portsidepro.com/podcast-feed/ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "guest_name": "Drew Pautler", "guest_title": "Creative Director at Good Fortunate Collective", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Drew Pautler, Founder and Creative Director of Good Fortune Collective, discuss a thought-provoking topic: what can the outdoor industry learn from mainstream sports?", "podcast_length": "37:05"}, {"id": "a0d46a2e-7402-477e-9b7b-a3c44f43fd76", "episode_id": "a05d7e73-aab7-45ac-842a-06ddc2c9830e", "cms_item_id": "68225dfc7bb476527f8c493c", "chunk_index": 1, "content": "Cole Heilborn (01:47): So I don't know what it is, maybe it's just because everyone's thinking about it these days, but many of our episodes that have been coming out recently are about the future of the industry, and I think that's no surprise, just given that as we've talked about to great lengths, our industry is in a bit of an inflection stage, and I think we're all trying to kind of read the tea leaves and figure out where is it going, what do we need to learn, what do we need to change? How do we improve the industry so that we can move forward stronger? And you had this question of there's so much that we can learn from mainstream sports, and if we could apply some of those lessons or fraction of those lessons to our outdoor industry, there's a lot we could learn. There's a lot we could probably benefit from. And so Drew, I'm curious, why is this a question that you're asking yourself? And then I'd love to kind of get into that and maybe we can even try to answer that question.\n\nDrew Pautler (02:43): Sure. I mean, it's just such an interesting time. I feel like with the outdoor industry, alternative sports and action sports and fully realizing that there's a lot of diversity within that group. And so I certainly don't mean to lump all together, but for so long it's been a space where we've tried to define and differentiate those experiences from mainstream sport. And in many cases, alt sports and the outdoor industry was the antithesis too, and that's all good. But we've come to a place where now as the sports have matured and more people are participating, how do we get over this hurdle of being fringe and being alternative and getting to a place where we can be more mainstream and being fully comfortable with that? And so it's something that I've wondered for a very long time and have some hypotheses and of course, some experience in working with some pretty incredible brands in this space. So yeah, just really excited to dive into that with you today.", "token_estimate": 499, "speakers": ["Cole Heilborn", "Drew Pautler"], "start_timestamp": "01:47", "end_timestamp": "02:43", "podcast_index": 178, "episode_name": "EP: 178 Breaking Barriers: What Can the Outdoor Industry Learn from Mainstream Sports?", "slug": "ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "web_url": "https://www.portsidepro.com/podcast-feed/ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "guest_name": "Drew Pautler", "guest_title": "Creative Director at Good Fortunate Collective", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Drew Pautler, Founder and Creative Director of Good Fortune Collective, discuss a thought-provoking topic: what can the outdoor industry learn from mainstream sports?", "podcast_length": "37:05"}, {"id": "0bc2b9d7-242d-44c0-8526-42cbb8588e4f", "episode_id": "a05d7e73-aab7-45ac-842a-06ddc2c9830e", "cms_item_id": "68225dfc7bb476527f8c493c", "chunk_index": 2, "content": "Cole Heilborn (03:49): Yeah, and before we go deeper, can you share a little bit about Good Fortune Collective, what you do, some of the folks you've worked with, and I dunno, maybe give us a highlight of a particular problem or something that you guys worked\n\nDrew Pautler (04:00): On? Sure, sure. So Good Fortune Collective is an agency I founded 11 years ago, and it was really founded under the notion of helping to amplify brands that are doing right by people and the planet. And so our mission is really to mainstream those brands and try and help them be the best version of themselves and be the most successful version of themselves. And that's of course, through cultural participation.\n\nCole Heilborn (04:28): So this word mainstream, does the outdoor industry cringe a little bit when we talk about maybe becoming mainstream? You mentioned we were kind of the anti mainstream for so long, and that's who we are. That's who were Yeah. Talk to me about that word. What does that mean to you?\n\nDrew Pautler (04:45): I mean, my sense is that if we were able to shed that stigma of mainstreaming being a bad thing, the whole industry would grow. And it would not only grow for more people, bringing more people into the sport, but it would also grow for people who would consider themselves dedicated and passionate enthusiasts or living a lifestyle of sport or even on the sort of tip of the spear, folks who might make a living or are considered core. And there's core rock climbers, surfers, mountain bikers. I mean, there's core adventurous and campers and so on. And the reality is that, or at least in my opinion, that more people doing it isn't bad for the planet. It's good.\n\nCole Heilborn (05:34): So yeah, talk to me about what is this idea of making the outdoor industry more mainstream? What does that do? Does that help, do you think that helps solve kind of the underlying issues that the industry faces?", "token_estimate": 482, "speakers": ["Cole Heilborn", "Drew Pautler"], "start_timestamp": "03:49", "end_timestamp": "05:34", "podcast_index": 178, "episode_name": "EP: 178 Breaking Barriers: What Can the Outdoor Industry Learn from Mainstream Sports?", "slug": "ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "web_url": "https://www.portsidepro.com/podcast-feed/ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "guest_name": "Drew Pautler", "guest_title": "Creative Director at Good Fortunate Collective", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Drew Pautler, Founder and Creative Director of Good Fortune Collective, discuss a thought-provoking topic: what can the outdoor industry learn from mainstream sports?", "podcast_length": "37:05"}, {"id": "72109935-f3fa-4bb9-b994-9f0c30513152", "episode_id": "a05d7e73-aab7-45ac-842a-06ddc2c9830e", "cms_item_id": "68225dfc7bb476527f8c493c", "chunk_index": 3, "content": "Drew Pautler (05:46): I think that it would help us get out of the echo chamber of talking to ourselves. And there's a comfort in that it's a place that the industry knows so well. And there is a style of marketing that definitely benefits by flexing your knowledge of a particular space and using insights that are derived that you would only know if you've been out in the water before the sun came up, or you might only know if you've been in a particular dirt condition on a mountain bike. And of course, every sport has their own nuance there. And so to flex that sort of cultural withitness within the sport is a way to demonstrate your leadership position. And so you can see how many brands have really run towards that to try and flex their legitimacy to try and demonstrate that they get it, that they understand what people who are doing the sport might go through and ultimately earning cool points along the way. And while all of that is important, it's something that can be quite insular. It's something that can also be seen as quite elitist in that this sport is for us and not them. And those are just constructs and ideologies that I think we need to shed.\n\nCole Heilborn (07:19): And in doing so, hopefully, because I mean, I think at the root of this conversation, the root of the problem that we're trying to solve is how do we make the outdoors more appealing to other people who aren't already the people doing the things right? And making something that's mainstream and resonating with the mainstream culture is a way to do that. Is that what you're saying?\n\nDrew Pautler (07:41): Yeah. And I think that it's important to just have a couple of caveats here. I mean, obviously this is the Backcountry Marketing podcast, and so that's\n\nCole Heilborn (07:51): Speaking to the core,", "token_estimate": 451, "speakers": ["Drew Pautler", "Cole Heilborn"], "start_timestamp": "05:46", "end_timestamp": "07:51", "podcast_index": 178, "episode_name": "EP: 178 Breaking Barriers: What Can the Outdoor Industry Learn from Mainstream Sports?", "slug": "ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "web_url": "https://www.portsidepro.com/podcast-feed/ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "guest_name": "Drew Pautler", "guest_title": "Creative Director at Good Fortunate Collective", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Drew Pautler, Founder and Creative Director of Good Fortune Collective, discuss a thought-provoking topic: what can the outdoor industry learn from mainstream sports?", "podcast_length": "37:05"}, {"id": "0d1fc80d-5255-4f77-8cdb-f77a801b8506", "episode_id": "a05d7e73-aab7-45ac-842a-06ddc2c9830e", "cms_item_id": "68225dfc7bb476527f8c493c", "chunk_index": 4, "content": "Drew Pautler (07:52): Well, we're speaking to the core, but I'm referencing that because there's a lot of factors outside of marketing that influence the growth of sport and the outdoor industry as a whole. There's proximity to places of practice, there's socioeconomics and affordability, there's accessibility because hey, not everyone has the modes of moving through spaces and participation. So there's a lot of things that influence growing sport. But I think that there's a hidden, not talked about factor that could grow our sport, that mainstream sports has absolutely nailed that the outdoor industry where appropriate, and I'll get to that asterisk in a moment, could really draw some inspiration and bring more people in.\n\nCole Heilborn (08:49): Okay. Yeah. So if you had to compare mainstream sports, and let's just define those, I dunno, football, soccer, hockey, would you add any to that list?", "token_estimate": 227, "speakers": ["Drew Pautler", "Cole Heilborn"], "start_timestamp": "07:52", "end_timestamp": "08:49", "podcast_index": 178, "episode_name": "EP: 178 Breaking Barriers: What Can the Outdoor Industry Learn from Mainstream Sports?", "slug": "ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "web_url": "https://www.portsidepro.com/podcast-feed/ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "guest_name": "Drew Pautler", "guest_title": "Creative Director at Good Fortunate Collective", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Drew Pautler, Founder and Creative Director of Good Fortune Collective, discuss a thought-provoking topic: what can the outdoor industry learn from mainstream sports?", "podcast_length": "37:05"}, {"id": "12bf5755-a8bd-4f02-b94a-f11859f0a6c4", "episode_id": "a05d7e73-aab7-45ac-842a-06ddc2c9830e", "cms_item_id": "68225dfc7bb476527f8c493c", "chunk_index": 5, "content": "Drew Pautler (08:59): Baseball? Yeah, sure. I mean, just to think about some of the, I don't want to call 'em traditional, but mainstream sports, depending on where you are in the world, it would be cricket, it would be American football versus of course football or soccer. For us North Americans, it's tennis, it's rugby in certain places. Just thinking of our friends down in New Zealand and Australia. And then of course for my fellow Canadians, and I know that this is a global sport, but ice hockey is another one that we could fit into the major league kind of mainstream sport classification. And someone might make the joke that these are stick and ball sports, and these are all team sports, and of course they are team sports. But the reality is is that a lot of outdoor sport and a lot of outdoor recreation is stuff that you can do individually as well as within a group context or a team context. (09:59): And the experiences can be radically different, and therefore we should be able to have more people participating, not less, because you don't need a team. I mean, you can shoot puck, but you can't play ice hockey on your own. You can shoot hoops, but you can't play one on none. But you can ride a bicycle by yourself, you can go running by yourself. But of course those sports are enhanced when you do it with others. And so again, there's a really interesting tension there in that, hey, the modes of enjoying some of the outdoor sports are more diverse, and yet we have less participation.\n\nCole Heilborn (10:39): So if you had to compare what those mainstream sports have done versus the outdoor industry, what are the main, I guess I'm trying to understand how do these things become mainstream? And I think there's so many elements at play, but if you had to, I don't know, summarize or take a guess as to what makes those sports culturally mainstream, what are some of those attributes?", "token_estimate": 479, "speakers": ["Drew Pautler", "Cole Heilborn"], "start_timestamp": "08:59", "end_timestamp": "10:39", "podcast_index": 178, "episode_name": "EP: 178 Breaking Barriers: What Can the Outdoor Industry Learn from Mainstream Sports?", "slug": "ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "web_url": "https://www.portsidepro.com/podcast-feed/ep-178-breaking-the-barriers-what-can-the-outdoor-industry-learn-from-mainstream-sports", "guest_name": "Drew Pautler", "guest_title": "Creative Director at Good Fortunate Collective", "categories": ["industry-trends"], "short_description": "In this conversation, Cole and Drew Pautler, Founder and Creative Director of Good Fortune Collective, discuss a thought-provoking topic: what can the outdoor industry learn from mainstream sports?", "podcast_length": "37:05"}]
